'use client'

import Link from 'next/link'
import { ArrowLeft } from 'lucide-react'
import { t } from '@/lib/i18n'
import { useLang } from '@/lib/useLang'
import Footer from '../components/Footer'
import { TRANSLATION_NOTE } from '@/lib/legal-note'

const ISSUES = 'https://github.com/NeverFirstTry/metablend/issues'
const PLAUSIBLE = 'https://plausible.io/privacy'

const A = ({ href, children }) => (
  <a href={href} target="_blank" rel="noopener noreferrer" className="text-emerald-400 hover:underline">{children}</a>
)

// Full notice per language. Structure mirrors the English original; the
// substance (what is collected, retention, recipients) must stay identical
// across languages — change all of them together.
const CONTENT = {
  en: {
    updated: 'Last updated November 2026',
    t1: 'Privacy ', t2: 'Notice',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.en}</em><br /><br />MetaBlend is a free, in-development weather app with <strong>no accounts</strong> (the only sign-up is the optional Android tester list). We keep data collection to the minimum needed to run the service and to measure how accurate each weather source is. This is a plain-language summary, not legal advice.</>,
    sections: [
      { title: 'Controller', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Austria<br />Email: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'What stays on your device', body: <>We store a few small preferences locally so the app remembers your choices: language, temperature unit, theme, your selected forecast range, your consent to this notice, and your recently searched and saved cities. The last forecast you viewed is cached so the app still works offline. Language, unit, theme, your consent and recent cities are kept as cookies, so they reach our server with each page request; it does not store them. Everything else stays in your browser. You can clear it all anytime by clearing your site data.</> },
      { title: 'Weather feedback you submit', body: <>When you report “how’s the weather right now,” we store the city, the temperature and condition you entered, the date, and the searched city’s approximate map coordinates (from our geocoder — never your device’s GPS position). This is used to score how close each weather source was, and reports appear as city-level points on the public accuracy heatmap. It is not linked to your name, email, or any account, because there are none. The legal basis is our legitimate interest in measuring and improving the accuracy of the weather sources (Art. 6(1)(f) GDPR).</> },
      { title: 'Technical data', body: <>To stop abuse, we briefly use your IP address to rate-limit feedback (one report per city per hour). It is used in memory for that check and is not stored alongside your feedback. If a request fails, our server keeps the requested address in its error log for 30 days, without your device’s location: nothing from “my location”, and coordinates rounded to about 10 km (Art. 6(1)(f) GDPR, troubleshooting and stable operation).</> },
      { title: 'Hosting and server log files', body: <>This website is hosted by Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). When you visit it, Vercel processes technically necessary data: IP address, date and time, the page requested, browser and operating system information, and the previously visited page. This serves secure and stable operation (Art. 6(1)(f) GDPR, legitimate interest). The log files are stored only for a limited time and then deleted. A data processing agreement is in place with Vercel. Vercel is certified under the EU-US Data Privacy Framework; the transfer to the USA takes place on the basis of the European Commission’s adequacy decision (Art. 45 GDPR).</> },
      { title: 'Analytics', body: <>We use <A href={PLAUSIBLE}>Plausible Analytics</A>, a privacy-friendly, EU-hosted tool that counts visits <strong>without cookies</strong> and without collecting personal data. We only see aggregate numbers (e.g. page views), never individuals. We also use <strong>Vercel Speed Insights</strong>, which measures how quickly pages load (anonymous performance numbers such as load time), likewise without cookies and without identifying you. <strong>Vercel Web Analytics</strong> likewise counts page views without cookies. The legal basis for Plausible, Vercel Speed Insights and Vercel Web Analytics is our legitimate interest in a fast website and in knowing how it is used (Art. 6(1)(f) GDPR). Plausible processes your IP address only transiently, for a daily changing identifier, and does not store it.</> },
      { title: 'Third-party services', body: <>
        <p className="mb-2">To produce a forecast we send the city or coordinates you search to weather and geocoding providers, and we receive their data back:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (incl. geocoding, air quality, historical archive) — search suggestions go to it directly from your browser, so it sees your IP address</li>
          <li>Photon (komoot), OpenStreetMap and Overpass (overpass-api.de, private.coffee) — peak search and summit heights: the search text and, with “Near me”, a location rounded to about 10 km; for marked routes our server sends only the summit’s coordinates</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (US), Bright Sky (DWD), SMHI — plus ECMWF/GFS/ICON via Open-Meteo</li>
          <li>BigDataCloud — only if you use “my location”, to turn your coordinates into a city name (reverse geocoding)</li>
          <li>NOAA Aviation Weather (METAR reports) and Meteostat (via RapidAPI) — receive city coordinates server-side to fetch reference measurements that score each source&apos;s accuracy</li>
          <li>Map tiles by OpenStreetMap contributors (heatmap and rain radar) and OpenTopoMap (route maps in the app)</li>
          <li>Our own server — if you use “my location”, also your position rounded to about 10 km, to pick the right town of that name; your device remembers it for that town</li>
          <li>RainViewer (rain radar) and unpkg (the map library) — your browser loads these directly when a map opens, so they see your IP address and, for the radar, the map area</li>
          <li>Apple (APNs) and Google (FCM) — deliver notifications: they receive your phone’s push token and the alert’s text — both in the USA; Apple and Google are certified under the EU-US Data Privacy Framework, so the transfer rests on the European Commission’s adequacy decision (Art. 45 GDPR)</li>
          <li>ImprovMX and Google (Gmail) — forward and store emails sent to info@metablend.app — ImprovMX receives in the EU (France) and forwards partly through servers in the USA; Google is certified under the EU-US Data Privacy Framework (Art. 45 GDPR)</li>
        </ul>
        <p className="mt-2">The database runs on <strong>Supabase</strong> (EU region, Frankfurt). Each provider handles the data it receives under its own privacy policy.</p>
      </> },
      { title: 'Notifications (app)', body: <>If you turn on notifications in the app, we store your phone’s push token (from Apple or Google), a hash of a random key the app creates, your home city, which alerts you switched on and your briefing hour, planned peaks and dates, your language and unit, and a log of what we sent in the last 14 days. There is no account and no location. Phones that have neither opened the app nor received an alert for 90 days are deleted automatically, planned hikes after their day. Routes stay on your phone; a route you plan a hike on is stored with the plan to send its alerts and deleted with it. Turning notifications off in the app or deleting the app stops them. The legal basis is providing the service you switched on (Art. 6(1)(b) GDPR).</> },
      { title: 'Android tester sign-up', body: <>If you sign up on the testers page to test the Android app, we store the email address you enter and — only if you fill them in — your phone model and country, plus your language, the date and where you are in the process (new, added, opted in, removed). The address is used only to add you to MetaBlend’s closed test on Google Play and to send you the test link; Google then knows you as a tester under its own privacy policy. Phone model and country only help us spread testers across devices and regions. Your IP address is used briefly in memory to stop abuse and we do not store it. The list is deleted when the closed test ends (at the latest once the app is public on Google Play), or earlier if you ask: email <A href="mailto:info@metablend.app">info@metablend.app</A>. The legal basis is your consent (Art. 6(1)(a) GDPR); you can withdraw it at any time with effect for the future by asking us to delete your entry.</> },
      { title: 'How long we keep it', body: <>Stored forecasts and internal bookkeeping rows are automatically deleted by a daily cleanup job (typically within about 48 hours); consensus snapshots and server error logs are deleted after 30 days. Community feedback reports are kept for as long as they power the public accuracy heatmap and the long-term source rankings — or until you ask us to remove them (see below). Aggregate accuracy weights are anonymous and kept indefinitely.</> },
      { title: 'Your rights and choices', body: <><p className="mb-2">You have the right of access, rectification, erasure, restriction of processing, data portability and objection. To exercise them, write to <A href="mailto:info@metablend.app">info@metablend.app</A>. You can also lodge a complaint with the Austrian Data Protection Authority (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>You can use the app without sharing your location, clear your locally stored preferences anytime, and request removal of feedback data by opening an issue on our <A href={ISSUES}>GitHub repository</A>.</p></> },
      { title: 'Contact', body: <><p className="mb-2">Questions about privacy? Email <A href="mailto:info@metablend.app">info@metablend.app</A> or open an issue at <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. As MetaBlend evolves, this notice may change; the “last updated” date above will always reflect the current version.</p><p>If you contact us by email, we process your email address and the content of your message in order to answer your enquiry (Art. 6(1)(b) or (f) GDPR). The data are deleted once the enquiry has been dealt with and no statutory retention obligations apply.</p></> },
    ],
  },

  de: {
    updated: 'Zuletzt aktualisiert November 2026',
    t1: 'Datenschutz', t2: 'erklärung',
    intro: <>MetaBlend ist eine kostenlose Wetter-App in Entwicklung — <strong>ohne Konten</strong> (die einzige Anmeldung ist die freiwillige Android-Testerliste). Wir sammeln nur so wenige Daten, wie für den Betrieb und die Genauigkeitsmessung der Wetterquellen nötig sind. Dies ist eine Zusammenfassung in einfacher Sprache, keine Rechtsberatung.</>,
    sections: [
      { title: 'Verantwortlicher', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Österreich<br />E-Mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Was auf Ihrem Gerät bleibt', body: <>Ein paar kleine Einstellungen werden lokal gespeichert, damit die App Ihre Auswahl behält: Sprache, Temperatureinheit, Design, den gewählten Vorhersagezeitraum, Ihre Zustimmung zu diesem Hinweis sowie zuletzt gesuchte und gespeicherte Städte. Die zuletzt angesehene Vorhersage wird zwischengespeichert, damit die App auch offline funktioniert. Sprache, Einheit, Design, Ihre Zustimmung und zuletzt gesuchte Städte liegen in Cookies und erreichen daher bei jedem Seitenaufruf unseren Server, der sie nicht speichert. Alles andere bleibt in Ihrem Browser. Sie können alles jederzeit über die Website-Daten Ihres Browsers löschen.</> },
      { title: 'Wetter-Feedback, das Sie einreichen', body: <>Wenn Sie melden, „wie das Wetter gerade ist“, speichern wir die Stadt, die eingegebene Temperatur und Wetterlage, das Datum und die ungefähren Kartenkoordinaten der gesuchten Stadt (aus unserem Geocoder — niemals die GPS-Position Ihres Geräts). Damit wird bewertet, wie nah jede Wetterquelle an der Wahrheit lag; Meldungen erscheinen als Punkte auf Stadtebene in der öffentlichen Genauigkeits-Heatmap. Eine Verknüpfung mit Name, E-Mail oder Konto gibt es nicht — es existieren keine Konten. Rechtsgrundlage ist unser berechtigtes Interesse, die Genauigkeit der Wetterquellen zu messen und zu verbessern (Art. 6 Abs. 1 lit. f DSGVO).</> },
      { title: 'Technische Daten', body: <>Um Missbrauch zu verhindern, verwenden wir Ihre IP-Adresse kurzzeitig zur Begrenzung von Feedback (eine Meldung pro Stadt und Stunde). Sie wird nur im Arbeitsspeicher für diese Prüfung genutzt und nicht zusammen mit Ihrem Feedback gespeichert. Schlägt eine Anfrage fehl, behält unser Server die aufgerufene Adresse 30 Tage lang im Fehlerprotokoll, ohne Ihren Gerätestandort: nichts aus „Mein Standort“, Koordinaten nur auf etwa 10 km gerundet (Art. 6 Abs. 1 lit. f DSGVO, Fehlerbehebung und stabiler Betrieb).</> },
      { title: 'Hosting und Server-Logfiles', body: <>Diese Website wird bei Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA) gehostet. Beim Aufruf verarbeitet Vercel technisch notwendige Daten: IP-Adresse, Datum und Uhrzeit, aufgerufene Seite, Browser- und Betriebssysteminformationen sowie die zuvor besuchte Seite. Das dient dem sicheren und stabilen Betrieb (Art. 6 Abs. 1 lit. f DSGVO, berechtigtes Interesse). Die Logfiles werden nur für begrenzte Zeit gespeichert und danach gelöscht. Mit Vercel besteht ein Auftragsverarbeitungsvertrag. Vercel ist nach dem EU-US Data Privacy Framework zertifiziert; die Übermittlung in die USA erfolgt auf Grundlage des Angemessenheitsbeschlusses der EU-Kommission (Art. 45 DSGVO).</> },
      { title: 'Analyse', body: <>Wir verwenden <A href={PLAUSIBLE}>Plausible Analytics</A>, ein datenschutzfreundliches, in der EU gehostetes Tool, das Besuche <strong>ohne Cookies</strong> und ohne personenbezogene Daten zählt. Wir sehen nur Gesamtzahlen (z.&nbsp;B. Seitenaufrufe), nie Einzelpersonen. Außerdem nutzen wir <strong>Vercel Speed Insights</strong>, das misst, wie schnell Seiten laden (anonyme Leistungswerte wie die Ladezeit) — ebenfalls ohne Cookies und ohne Sie zu identifizieren. Auch <strong>Vercel Web Analytics</strong> zählt Seitenaufrufe ohne Cookies. Rechtsgrundlage für Plausible, Vercel Speed Insights und Vercel Web Analytics ist unser berechtigtes Interesse an einer schnellen Website und daran zu wissen, wie sie genutzt wird (Art. 6 Abs. 1 lit. f DSGVO). Plausible verarbeitet Ihre IP-Adresse dabei nur flüchtig für einen täglich wechselnden Kennwert und speichert sie nicht.</> },
      { title: 'Dienste von Drittanbietern', body: <>
        <p className="mb-2">Für eine Vorhersage senden wir die gesuchte Stadt bzw. deren Koordinaten an Wetter- und Geocoding-Anbieter und erhalten deren Daten zurück:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (inkl. Geocoding, Luftqualität, historisches Archiv) — Suchvorschläge gehen direkt aus Ihrem Browser dorthin, Open-Meteo sieht daher Ihre IP-Adresse</li>
          <li>Photon (komoot), OpenStreetMap und Overpass (overpass-api.de, private.coffee) — Gipfelsuche und Gipfelhöhen: der Suchtext und bei „In meiner Nähe“ ein auf etwa 10 km gerundeter Standort; für markierte Routen sendet unser Server nur die Koordinaten des Gipfels</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (US), Bright Sky (DWD), SMHI — sowie ECMWF/GFS/ICON über Open-Meteo</li>
          <li>BigDataCloud — nur bei „Mein Standort“, um Koordinaten in einen Stadtnamen zu übersetzen (Reverse-Geocoding)</li>
          <li>NOAA Aviation Weather (METAR-Meldungen) und Meteostat (über RapidAPI) — erhalten serverseitig Stadtkoordinaten, um Referenzmessungen für die Genauigkeitsbewertung abzurufen</li>
          <li>Kartenkacheln von OpenStreetMap-Mitwirkenden (Heatmap und Regenradar) und OpenTopoMap (Routenkarten in der App)</li>
          <li>Unser eigener Server — bei „Mein Standort“ zusätzlich Ihre auf etwa 10 km gerundete Position, um den richtigen Ort dieses Namens zu wählen; Ihr Gerät merkt sie sich für diesen Ort</li>
          <li>RainViewer (Regenradar) und unpkg (die Kartenbibliothek) — Ihr Browser lädt sie direkt, sobald sich eine Karte öffnet; sie sehen daher Ihre IP-Adresse und beim Radar den Kartenausschnitt</li>
          <li>Apple (APNs) und Google (FCM) — stellen Benachrichtigungen zu und erhalten dafür den Push-Token Ihres Telefons und den Text des Hinweises — beide in den USA; Apple und Google sind nach dem EU-US Data Privacy Framework zertifiziert, die Übermittlung stützt sich auf den Angemessenheitsbeschluss der EU-Kommission (Art. 45 DSGVO)</li>
          <li>ImprovMX und Google (Gmail) — leiten E-Mails an info@metablend.app weiter und speichern sie — ImprovMX empfängt in der EU (Frankreich) und leitet teils über Server in den USA weiter; Google ist nach dem EU-US Data Privacy Framework zertifiziert (Art. 45 DSGVO)</li>
        </ul>
        <p className="mt-2">Die Datenbank läuft auf <strong>Supabase</strong> (EU-Region, Frankfurt). Jeder Anbieter verarbeitet die erhaltenen Daten nach seiner eigenen Datenschutzerklärung.</p>
      </> },
      { title: 'Benachrichtigungen (App)', body: <>Wenn Sie in der App Benachrichtigungen einschalten, speichern wir den Push-Token Ihres Telefons (von Apple oder Google), einen Hash eines zufälligen Schlüssels, den die App erzeugt, Ihre Heimatstadt, welche Hinweise Sie eingeschaltet haben und die Uhrzeit Ihres Morgenberichts, geplante Gipfel und Tage, Sprache und Einheit sowie ein Protokoll dessen, was wir in den letzten 14 Tagen gesendet haben. Es gibt kein Konto und keinen Standort. Telefone, die 90 Tage lang weder die App geöffnet noch einen Hinweis erhalten haben, werden automatisch gelöscht, geplante Touren nach ihrem Tag. Routen bleiben auf Ihrem Telefon; eine Route, auf der Sie eine Tour planen, wird mit dem Plan gespeichert, um ihre Hinweise zu senden, und mit ihm gelöscht. Benachrichtigungen in der App ausschalten oder die App löschen beendet sie. Rechtsgrundlage ist die Bereitstellung des von Ihnen eingeschalteten Dienstes (Art. 6 Abs. 1 lit. b DSGVO).</> },
      { title: 'Anmeldung als Android-Tester', body: <>Wenn Sie sich auf der Tester-Seite für den Test der Android-App anmelden, speichern wir die eingegebene E-Mail-Adresse und – nur wenn Sie sie ausfüllen – Ihr Handymodell und Land, außerdem Ihre Sprache, das Datum und den Stand (neu, hinzugefügt, beigetreten, entfernt). Die Adresse wird nur verwendet, um Sie zum geschlossenen Test von MetaBlend bei Google Play hinzuzufügen und Ihnen den Testlink zu schicken; Google kennt Sie dann als Tester nach seiner eigenen Datenschutzerklärung. Handymodell und Land helfen uns nur, Tester auf verschiedene Geräte und Regionen zu verteilen. Ihre IP-Adresse wird kurz im Arbeitsspeicher genutzt, um Missbrauch zu verhindern, und von uns nicht gespeichert. Die Liste wird gelöscht, wenn der geschlossene Test endet (spätestens, sobald die App öffentlich bei Google Play ist), oder früher auf Wunsch: Schreiben Sie an <A href="mailto:info@metablend.app">info@metablend.app</A>. Rechtsgrundlage ist Ihre Einwilligung (Art. 6 Abs. 1 lit. a DSGVO); Sie können sie jederzeit mit Wirkung für die Zukunft widerrufen, indem Sie um Löschung bitten.</> },
      { title: 'Wie lange wir Daten aufbewahren', body: <>Gespeicherte Vorhersagen und interne Verwaltungseinträge werden von einem täglichen Aufräumjob automatisch gelöscht (in der Regel innerhalb von etwa 48 Stunden); Konsens-Snapshots und Server-Fehlerprotokolle nach 30 Tagen. Community-Feedback bleibt länger erhalten — es speist die öffentliche Heatmap und die langfristigen Ranglisten — bis Sie um Löschung bitten (siehe unten). Aggregierte Genauigkeitsgewichte sind anonym und werden unbegrenzt aufbewahrt.</> },
      { title: 'Ihre Rechte und Möglichkeiten', body: <><p className="mb-2">Sie haben das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit und Widerspruch. Schreiben Sie dazu an <A href="mailto:info@metablend.app">info@metablend.app</A>. Sie können sich außerdem bei der Österreichischen Datenschutzbehörde beschweren (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Sie können die App ohne Standortfreigabe nutzen, Ihre lokal gespeicherten Einstellungen jederzeit löschen und die Entfernung von Feedback-Daten über ein Issue in unserem <A href={ISSUES}>GitHub-Repository</A> beantragen.</p></> },
      { title: 'Kontakt', body: <><p className="mb-2">Fragen zum Datenschutz? Schreiben Sie an <A href="mailto:info@metablend.app">info@metablend.app</A> oder öffnen Sie ein Issue unter <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. MetaBlend entwickelt sich weiter; das Datum „zuletzt aktualisiert“ oben zeigt immer die aktuelle Fassung.</p><p>Wenn Sie uns per E-Mail kontaktieren, verarbeiten wir Ihre E-Mail-Adresse und den Inhalt Ihrer Nachricht, um Ihre Anfrage zu beantworten (Art. 6 Abs. 1 lit. b bzw. f DSGVO). Die Daten werden gelöscht, sobald die Anfrage erledigt ist und keine gesetzlichen Aufbewahrungspflichten bestehen.</p></> },
    ],
  },

  fr: {
    updated: 'Dernière mise à jour : novembre 2026',
    t1: 'Politique de ', t2: 'confidentialité',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.fr}</em><br /><br />MetaBlend est une application météo gratuite, en cours de développement, <strong>sans compte</strong> (la seule inscription est la liste facultative des testeurs Android). Nous limitons la collecte de données au strict nécessaire pour faire fonctionner le service et mesurer la précision de chaque source météo. Ceci est un résumé en langage clair, pas un avis juridique.</>,
    sections: [
      { title: 'Responsable du traitement', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Autriche<br />E-mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Ce qui reste sur votre appareil', body: <>Quelques petites préférences sont stockées localement pour que l’application retienne vos choix : langue, unité de température, thème, la période de prévision choisie, votre consentement à cette notice, ainsi que vos villes recherchées et enregistrées. La dernière prévision consultée est mise en cache pour que l’application fonctionne hors ligne. La langue, l’unité, le thème, votre consentement et les villes récentes sont conservés dans des cookies et parviennent donc à notre serveur à chaque chargement de page ; il ne les enregistre pas. Tout le reste demeure dans votre navigateur. Vous pouvez tout effacer à tout moment via les données de site de votre navigateur.</> },
      { title: 'Les signalements météo que vous envoyez', body: <>Quand vous signalez « le temps qu’il fait en ce moment », nous enregistrons la ville, la température et la condition saisies, la date, ainsi que les coordonnées approximatives de la ville recherchée (issues de notre géocodeur — jamais la position GPS de votre appareil). Ces données servent à évaluer la précision de chaque source météo, et les signalements apparaissent comme des points à l’échelle de la ville sur la carte de précision publique. Ils ne sont liés à aucun nom, e-mail ou compte, puisqu’il n’en existe pas. La base juridique est notre intérêt légitime à mesurer et à améliorer la précision des sources météo (art. 6, par. 1, point f du RGPD).</> },
      { title: 'Données techniques', body: <>Pour empêcher les abus, nous utilisons brièvement votre adresse IP afin de limiter les signalements (un par ville et par heure). Elle n’est utilisée qu’en mémoire pour ce contrôle et n’est pas stockée avec votre signalement. Si une requête échoue, notre serveur conserve l’adresse demandée 30 jours dans son journal d’erreurs, sans la position de votre appareil : rien de « Ma position », et des coordonnées arrondies à environ 10 km (art. 6, par. 1, point f du RGPD, dépannage et fonctionnement stable).</> },
      { title: 'Hébergement et journaux du serveur', body: <>Ce site est hébergé par Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Lors de la consultation, Vercel traite des données techniquement nécessaires : adresse IP, date et heure, page consultée, informations sur le navigateur et le système d’exploitation ainsi que la page visitée précédemment. Cela sert à l’exploitation sûre et stable (art. 6, par. 1, point f du RGPD, intérêt légitime). Les journaux ne sont conservés que pendant une durée limitée, puis supprimés. Un contrat de sous-traitance est conclu avec Vercel. Vercel est certifié selon le EU-US Data Privacy Framework ; le transfert vers les États-Unis repose sur la décision d’adéquation de la Commission européenne (art. 45 du RGPD).</> },
      { title: 'Statistiques', body: <>Nous utilisons <A href={PLAUSIBLE}>Plausible Analytics</A>, un outil respectueux de la vie privée et hébergé dans l’UE, qui compte les visites <strong>sans cookies</strong> et sans collecter de données personnelles. Nous ne voyons que des chiffres agrégés (p. ex. pages vues), jamais des individus. Nous utilisons aussi <strong>Vercel Speed Insights</strong>, qui mesure la vitesse de chargement des pages (des mesures de performance anonymes, comme le temps de chargement), également sans cookies et sans vous identifier. <strong>Vercel Web Analytics</strong> compte lui aussi les pages vues sans cookies. La base juridique pour Plausible, Vercel Speed Insights et Vercel Web Analytics est notre intérêt légitime à un site rapide et à savoir comment il est utilisé (art. 6, par. 1, point f du RGPD). Plausible ne traite votre adresse IP que de façon passagère, pour un identifiant qui change chaque jour, et ne la conserve pas.</> },
      { title: 'Services tiers', body: <>
        <p className="mb-2">Pour produire une prévision, nous envoyons la ville ou les coordonnées recherchées à des fournisseurs de météo et de géocodage, qui nous renvoient leurs données :</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (y compris géocodage, qualité de l’air, archives historiques) — les suggestions de recherche y vont directement depuis votre navigateur, Open-Meteo voit donc votre adresse IP</li>
          <li>Photon (komoot), OpenStreetMap et Overpass (overpass-api.de, private.coffee) — recherche de sommets et altitudes : le texte recherché et, avec « Près de moi », une position arrondie à environ 10 km ; pour les itinéraires balisés, notre serveur n’envoie que les coordonnées du sommet</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (US), Bright Sky (DWD), SMHI — ainsi que ECMWF/GFS/ICON via Open-Meteo</li>
          <li>BigDataCloud — uniquement si vous utilisez « ma position », pour convertir vos coordonnées en nom de ville (géocodage inverse)</li>
          <li>NOAA Aviation Weather (relevés METAR) et Meteostat (via RapidAPI) — reçoivent côté serveur les coordonnées des villes pour récupérer des mesures de référence servant à noter la précision de chaque source</li>
          <li>Tuiles cartographiques des contributeurs OpenStreetMap (carte et radar de pluie) et OpenTopoMap (cartes d’itinéraires dans l’app)</li>
          <li>Notre propre serveur — avec « Ma position », aussi votre position arrondie à environ 10 km, pour choisir la bonne localité de ce nom ; votre appareil la mémorise pour cette localité</li>
          <li>RainViewer (radar de pluie) et unpkg (la bibliothèque de cartes) — votre navigateur les charge directement à l’ouverture d’une carte ; ils voient donc votre adresse IP et, pour le radar, la zone affichée</li>
          <li>Apple (APNs) et Google (FCM) — acheminent les notifications : ils reçoivent le jeton push de votre téléphone et le texte de l’alerte — tous deux aux États-Unis ; Apple et Google sont certifiés au titre du cadre de protection des données UE–États-Unis, le transfert repose donc sur la décision d’adéquation de la Commission européenne (art. 45 du RGPD)</li>
          <li>ImprovMX et Google (Gmail) — transfèrent et conservent les e-mails envoyés à info@metablend.app — ImprovMX reçoit dans l’UE (France) et transfère en partie via des serveurs aux États-Unis ; Google est certifié au titre du cadre de protection des données UE–États-Unis (art. 45 du RGPD)</li>
        </ul>
        <p className="mt-2">La base de données est hébergée sur <strong>Supabase</strong> (région UE, Francfort). Chaque fournisseur traite les données reçues selon sa propre politique de confidentialité.</p>
      </> },
      { title: 'Notifications (app)', body: <>Si vous activez les notifications dans l’app, nous enregistrons le jeton push de votre téléphone (d’Apple ou de Google), l’empreinte d’une clé aléatoire créée par l’app, votre ville principale, les alertes activées et l’heure de votre point du matin, les sommets et dates prévus, votre langue et votre unité, ainsi qu’un journal de ce que nous avons envoyé ces 14 derniers jours. Aucun compte, aucune position. Les téléphones qui n’ont ni ouvert l’app ni reçu d’alerte depuis 90 jours sont supprimés automatiquement, les randonnées prévues après leur jour. Les itinéraires restent sur votre téléphone ; un itinéraire sur lequel vous planifiez une randonnée est enregistré avec le plan pour envoyer ses alertes et supprimé avec lui. Désactiver les notifications dans l’app ou supprimer l’app les arrête. La base juridique est la fourniture du service que vous avez activé (art. 6, par. 1, point b du RGPD).</> },
      { title: 'Inscription des testeurs Android', body: <>Si vous vous inscrivez sur la page des testeurs pour tester l’app Android, nous enregistrons l’adresse e-mail saisie et — seulement si vous les indiquez — votre modèle de téléphone et votre pays, ainsi que votre langue, la date et l’étape où vous en êtes (nouveau, ajouté, inscrit au test, retiré). L’adresse sert uniquement à vous ajouter au test fermé de MetaBlend sur Google Play et à vous envoyer le lien du test ; Google vous connaît alors comme testeur selon sa propre politique de confidentialité. Le modèle de téléphone et le pays nous aident seulement à répartir les testeurs entre appareils et régions. Votre adresse IP est utilisée brièvement en mémoire pour empêcher les abus et nous ne l’enregistrons pas. La liste est supprimée à la fin du test fermé (au plus tard quand l’app est publique sur Google Play), ou plus tôt sur demande : écrivez à <A href="mailto:info@metablend.app">info@metablend.app</A>. La base juridique est votre consentement (art. 6, par. 1, point a du RGPD) ; vous pouvez le retirer à tout moment pour l’avenir en demandant la suppression de votre inscription.</> },
      { title: 'Durée de conservation', body: <>Les prévisions stockées et les entrées internes de gestion sont supprimées automatiquement par un nettoyage quotidien (généralement sous 48 heures environ) ; les instantanés du consensus et les journaux d’erreurs du serveur sont supprimés après 30 jours. Les signalements de la communauté sont conservés plus longtemps — ils alimentent la carte de précision publique et les classements à long terme — ou jusqu’à ce que vous en demandiez la suppression (voir ci-dessous). Les pondérations agrégées de précision sont anonymes et conservées indéfiniment.</> },
      { title: 'Vos droits et vos choix', body: <><p className="mb-2">Vous disposez d’un droit d’accès, de rectification, d’effacement, de limitation du traitement, de portabilité des données et d’opposition. Pour cela, écrivez à <A href="mailto:info@metablend.app">info@metablend.app</A>. Vous pouvez également déposer une réclamation auprès de l’autorité autrichienne de protection des données (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Vous pouvez utiliser l’application sans partager votre position, effacer vos préférences locales à tout moment et demander la suppression de vos signalements en ouvrant un ticket sur notre <A href={ISSUES}>dépôt GitHub</A>.</p></> },
      { title: 'Contact', body: <><p className="mb-2">Des questions sur la confidentialité ? Écrivez à <A href="mailto:info@metablend.app">info@metablend.app</A> ou ouvrez un ticket sur <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. MetaBlend évolue ; la date de « dernière mise à jour » ci-dessus reflète toujours la version en vigueur.</p><p>Si vous nous contactez par e-mail, nous traitons votre adresse e-mail et le contenu de votre message afin de répondre à votre demande (art. 6, par. 1, point b ou f du RGPD). Les données sont supprimées dès que la demande est traitée et qu’aucune obligation légale de conservation ne s’applique.</p></> },
    ],
  },

  es: {
    updated: 'Última actualización: noviembre de 2026',
    t1: 'Aviso de ', t2: 'privacidad',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.es}</em><br /><br />MetaBlend es una app del tiempo gratuita y en desarrollo, <strong>sin cuentas</strong> (la única inscripción es la lista opcional de probadores de Android). Recogemos los datos mínimos necesarios para operar el servicio y medir la precisión de cada fuente meteorológica. Esto es un resumen en lenguaje claro, no asesoramiento legal.</>,
    sections: [
      { title: 'Responsable del tratamiento', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Austria<br />Correo electrónico: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Lo que se queda en su dispositivo', body: <>Guardamos localmente unas pocas preferencias para que la app recuerde sus elecciones: idioma, unidad de temperatura, tema, el periodo de previsión elegido, su consentimiento a este aviso y sus ciudades buscadas y guardadas. La última previsión que vio se guarda en caché para que la app funcione sin conexión. El idioma, la unidad, el tema, su consentimiento y las ciudades recientes se guardan en cookies, así que llegan a nuestro servidor con cada carga de página; no las almacena. Todo lo demás se queda en su navegador. Puede borrarlo todo cuando quiera limpiando los datos del sitio.</> },
      { title: 'El feedback meteorológico que envía', body: <>Cuando informa de «qué tiempo hace ahora», guardamos la ciudad, la temperatura y condición introducidas, la fecha y las coordenadas aproximadas de la ciudad buscada (de nuestro geocodificador — nunca la posición GPS de su dispositivo). Esto sirve para puntuar la precisión de cada fuente, y los informes aparecen como puntos a nivel de ciudad en el mapa público de precisión. No se vinculan a su nombre, correo ni cuenta alguna, porque no existen cuentas. La base jurídica es nuestro interés legítimo en medir y mejorar la precisión de las fuentes meteorológicas (art. 6.1.f RGPD).</> },
      { title: 'Datos técnicos', body: <>Para evitar abusos, usamos brevemente su dirección IP para limitar el feedback (un informe por ciudad y hora). Solo se usa en memoria para esa comprobación y no se almacena junto a su feedback. Si una solicitud falla, nuestro servidor conserva la dirección solicitada durante 30 días en su registro de errores, sin la ubicación de su dispositivo: nada de «Mi ubicación» y coordenadas redondeadas a unos 10 km (art. 6.1.f RGPD, resolución de errores y funcionamiento estable).</> },
      { title: 'Alojamiento y registros del servidor', body: <>Este sitio web está alojado en Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Al acceder a él, Vercel trata datos técnicamente necesarios: dirección IP, fecha y hora, página consultada, información del navegador y del sistema operativo, así como la página visitada anteriormente. Esto sirve para un funcionamiento seguro y estable (art. 6, apdo. 1, letra f del RGPD, interés legítimo). Los archivos de registro se conservan solo durante un tiempo limitado y después se eliminan. Existe un contrato de encargo del tratamiento con Vercel. Vercel está certificada conforme al EU-US Data Privacy Framework; la transferencia a EE. UU. se basa en la decisión de adecuación de la Comisión Europea (art. 45 del RGPD).</> },
      { title: 'Analítica', body: <>Usamos <A href={PLAUSIBLE}>Plausible Analytics</A>, una herramienta respetuosa con la privacidad y alojada en la UE que cuenta visitas <strong>sin cookies</strong> y sin recopilar datos personales. Solo vemos cifras agregadas (p. ej. páginas vistas), nunca individuos. También usamos <strong>Vercel Speed Insights</strong>, que mide lo rápido que cargan las páginas (datos de rendimiento anónimos, como el tiempo de carga), igualmente sin cookies y sin identificarle. <strong>Vercel Web Analytics</strong> también cuenta las visitas a páginas sin cookies. La base jurídica de Plausible, Vercel Speed Insights y Vercel Web Analytics es nuestro interés legítimo en un sitio rápido y en saber cómo se utiliza (art. 6.1.f RGPD). Plausible trata su dirección IP solo de forma pasajera, para un identificador que cambia cada día, y no la almacena.</> },
      { title: 'Servicios de terceros', body: <>
        <p className="mb-2">Para generar una previsión enviamos la ciudad o coordenadas que busca a proveedores de meteorología y geocodificación, y recibimos sus datos:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (incl. geocodificación, calidad del aire, archivo histórico) — las sugerencias de búsqueda van allí directamente desde su navegador, así que Open-Meteo ve su dirección IP</li>
          <li>Photon (komoot), OpenStreetMap y Overpass (overpass-api.de, private.coffee) — búsqueda de cumbres y altitudes: el texto buscado y, con «Cerca de mí», una ubicación redondeada a unos 10 km; para las rutas señalizadas nuestro servidor solo envía las coordenadas de la cumbre</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (US), Bright Sky (DWD), SMHI — además de ECMWF/GFS/ICON a través de Open-Meteo</li>
          <li>BigDataCloud — solo si usa «mi ubicación», para convertir sus coordenadas en un nombre de ciudad (geocodificación inversa)</li>
          <li>NOAA Aviation Weather (informes METAR) y Meteostat (a través de RapidAPI) — reciben coordenadas de ciudades en el servidor para obtener mediciones de referencia con las que puntuar la precisión de cada fuente</li>
          <li>Teselas de mapa de los colaboradores de OpenStreetMap (mapa y radar de lluvia) y OpenTopoMap (mapas de rutas en la app)</li>
          <li>Nuestro propio servidor — con «mi ubicación», también su posición redondeada a unos 10 km, para elegir la localidad correcta con ese nombre; su dispositivo la recuerda para esa localidad</li>
          <li>RainViewer (radar de lluvia) y unpkg (la biblioteca de mapas) — su navegador los carga directamente al abrir un mapa, así que ven su dirección IP y, en el radar, la zona del mapa</li>
          <li>Apple (APNs) y Google (FCM) — entregan las notificaciones: reciben el token push de su teléfono y el texto del aviso — ambos en EE. UU.; Apple y Google están certificados conforme al Marco de Privacidad de Datos UE-EE. UU., por lo que la transferencia se basa en la decisión de adecuación de la Comisión Europea (art. 45 RGPD)</li>
          <li>ImprovMX y Google (Gmail) — reenvían y guardan los correos enviados a info@metablend.app — ImprovMX recibe en la UE (Francia) y reenvía en parte a través de servidores en EE. UU.; Google está certificado conforme al Marco de Privacidad de Datos UE-EE. UU. (art. 45 RGPD)</li>
        </ul>
        <p className="mt-2">La base de datos se aloja en <strong>Supabase</strong> (región UE, Fráncfort). Cada proveedor trata los datos que recibe según su propia política de privacidad.</p>
      </> },
      { title: 'Notificaciones (app)', body: <>Si activa las notificaciones en la app, guardamos el token push de su teléfono (de Apple o Google), un hash de una clave aleatoria que crea la app, su ciudad principal, qué avisos activó y la hora de su resumen matinal, las cumbres y fechas planificadas, su idioma y unidad, y un registro de lo que enviamos en los últimos 14 días. No hay cuenta ni ubicación. Los teléfonos que en 90 días no abren la app ni reciben ningún aviso se borran automáticamente, las excursiones planificadas después de su día. Las rutas se quedan en su teléfono; una ruta en la que planifica una excursión se guarda con el plan para enviar sus avisos y se borra con él. Desactivar las notificaciones en la app o borrar la app las detiene. La base jurídica es la prestación del servicio que usted ha activado (art. 6.1.b RGPD).</> },
      { title: 'Inscripción de probadores de Android', body: <>Si se apunta en la página de probadores para probar la app de Android, guardamos la dirección de correo que introduce y —solo si los rellenas— su modelo de móvil y su país, además de su idioma, la fecha y en qué punto del proceso está (nuevo, añadido, inscrito, retirado). La dirección se usa solo para añadirle a la prueba cerrada de MetaBlend en Google Play y enviarle el enlace; Google le conoce entonces como probador según su propia política de privacidad. El modelo de móvil y el país solo nos ayudan a repartir los probadores entre dispositivos y regiones. Su dirección IP se usa brevemente en memoria para evitar abusos y no la guardamos. La lista se borra cuando termina la prueba cerrada (como muy tarde, cuando la app sea pública en Google Play), o antes si lo pide: escriba a <A href="mailto:info@metablend.app">info@metablend.app</A>. La base jurídica es su consentimiento (art. 6.1.a RGPD); puede retirarlo en cualquier momento con efecto futuro pidiendo que eliminemos su inscripción.</> },
      { title: 'Cuánto tiempo lo conservamos', body: <>Las previsiones almacenadas y los registros internos se eliminan automáticamente con una limpieza diaria (normalmente en unas 48 horas); las instantáneas del consenso y los registros de errores del servidor, a los 30 días. Los informes de la comunidad se conservan más tiempo — alimentan el mapa público de precisión y las clasificaciones a largo plazo — o hasta que pida que los eliminemos (ver abajo). Las ponderaciones agregadas de precisión son anónimas y se conservan indefinidamente.</> },
      { title: 'Sus derechos y opciones', body: <><p className="mb-2">Tiene derecho de acceso, rectificación, supresión, limitación del tratamiento, portabilidad de los datos y oposición. Para ello, escriba a <A href="mailto:info@metablend.app">info@metablend.app</A>. También puede presentar una reclamación ante la autoridad austriaca de protección de datos (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Puede usar la app sin compartir su ubicación, borrar sus preferencias locales cuando quiera y solicitar la eliminación de sus datos de feedback abriendo una incidencia en nuestro <A href={ISSUES}>repositorio de GitHub</A>.</p></> },
      { title: 'Contacto', body: <><p className="mb-2">¿Preguntas sobre privacidad? Escriba a <A href="mailto:info@metablend.app">info@metablend.app</A> o abra una incidencia en <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. MetaBlend sigue evolucionando; la fecha de «última actualización» de arriba refleja siempre la versión vigente.</p><p>Si nos contacta por correo electrónico, tratamos su dirección de correo y el contenido de su mensaje para responder a su consulta (art. 6, apdo. 1, letra b o f del RGPD). Los datos se eliminan en cuanto la consulta queda resuelta y no existan obligaciones legales de conservación.</p></> },
    ],
  },

  it: {
    updated: 'Ultimo aggiornamento: novembre 2026',
    t1: 'Informativa ', t2: 'Privacy',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.it}</em><br /><br />MetaBlend è un’app meteo gratuita e in sviluppo, <strong>senza account</strong> (l’unica iscrizione è la lista facoltativa dei tester Android). Raccogliamo il minimo di dati necessario per far funzionare il servizio e misurare la precisione di ogni fonte meteo. Questo è un riepilogo in linguaggio semplice, non una consulenza legale.</>,
    sections: [
      { title: 'Titolare del trattamento', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Austria<br />E-mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Cosa resta sul suo dispositivo', body: <>Salviamo localmente alcune piccole preferenze perché l’app ricordi le sue scelte: lingua, unità di temperatura, tema, il periodo di previsione scelto, il suo consenso a questa informativa e le città cercate e salvate di recente. L’ultima previsione visualizzata viene messa in cache così l’app funziona anche offline. Lingua, unità, tema, il suo consenso e le città recenti sono salvati in cookie, quindi raggiungono il nostro server a ogni caricamento di pagina; il server non li conserva. Tutto il resto rimane nel suo browser. Può cancellare tutto in qualsiasi momento eliminando i dati del sito.</> },
      { title: 'Il feedback meteo che invia', body: <>Quando segnala «che tempo fa adesso», salviamo la città, la temperatura e la condizione inserite, la data e le coordinate approssimative della città cercata (dal nostro geocoder — mai la posizione GPS del suo dispositivo). Servono a valutare quanto ogni fonte meteo si è avvicinata alla realtà, e le segnalazioni compaiono come punti a livello di città sulla mappa pubblica della precisione. Non sono collegate a nome, e-mail o account, perché non esistono account. La base giuridica è il nostro legittimo interesse a misurare e migliorare la precisione delle fonti meteo (art. 6, par. 1, lett. f GDPR).</> },
      { title: 'Dati tecnici', body: <>Per prevenire abusi usiamo brevemente il suo indirizzo IP per limitare il feedback (una segnalazione per città all’ora). Viene usato solo in memoria per quel controllo e non viene salvato insieme al suo feedback. Se una richiesta fallisce, il nostro server conserva l’indirizzo richiesto per 30 giorni nel registro degli errori, senza la posizione del suo dispositivo: nulla da «La mia posizione» e coordinate arrotondate a circa 10 km (art. 6, par. 1, lett. f GDPR, risoluzione degli errori e funzionamento stabile).</> },
      { title: 'Hosting e file di log del server', body: <>Questo sito web è ospitato da Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Alla visita, Vercel tratta dati tecnicamente necessari: indirizzo IP, data e ora, pagina richiesta, informazioni su browser e sistema operativo e la pagina visitata in precedenza. Ciò serve al funzionamento sicuro e stabile (art. 6, par. 1, lett. f GDPR, legittimo interesse). I file di log sono conservati solo per un periodo limitato e poi cancellati. Con Vercel è in essere un accordo sul trattamento dei dati. Vercel è certificata secondo l’EU-US Data Privacy Framework; il trasferimento verso gli USA avviene sulla base della decisione di adeguatezza della Commissione europea (art. 45 GDPR).</> },
      { title: 'Analisi', body: <>Usiamo <A href={PLAUSIBLE}>Plausible Analytics</A>, uno strumento rispettoso della privacy e ospitato nell’UE che conta le visite <strong>senza cookie</strong> e senza raccogliere dati personali. Vediamo solo numeri aggregati (es. pagine viste), mai singole persone. Usiamo anche <strong>Vercel Speed Insights</strong>, che misura la velocità di caricamento delle pagine (dati di prestazione anonimi, come il tempo di caricamento), anch’esso senza cookie e senza identificarla. Anche <strong>Vercel Web Analytics</strong> conta le visualizzazioni di pagina senza cookie. La base giuridica per Plausible, Vercel Speed Insights e Vercel Web Analytics è il nostro legittimo interesse a un sito veloce e a sapere come viene utilizzato (art. 6, par. 1, lett. f GDPR). Plausible tratta il Suo indirizzo IP solo in modo transitorio, per un identificativo che cambia ogni giorno, e non lo conserva.</> },
      { title: 'Servizi di terze parti', body: <>
        <p className="mb-2">Per produrre una previsione inviamo la città o le coordinate cercate a fornitori di dati meteo e geocoding, e riceviamo i loro dati:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (incl. geocoding, qualità dell’aria, archivio storico) — i suggerimenti di ricerca vi arrivano direttamente dal suo browser, quindi Open-Meteo vede il suo indirizzo IP</li>
          <li>Photon (komoot), OpenStreetMap e Overpass (overpass-api.de, private.coffee) — ricerca delle vette e quote: il testo cercato e, con «Vicino a me», una posizione arrotondata a circa 10 km; per i percorsi segnalati il nostro server invia solo le coordinate della vetta</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (US), Bright Sky (DWD), SMHI — oltre a ECMWF/GFS/ICON tramite Open-Meteo</li>
          <li>BigDataCloud — solo se usa «la mia posizione», per convertire le coordinate in un nome di città (geocoding inverso)</li>
          <li>NOAA Aviation Weather (bollettini METAR) e Meteostat (tramite RapidAPI) — ricevono lato server le coordinate delle città per ottenere misurazioni di riferimento con cui valutare la precisione di ogni fonte</li>
          <li>Tessere mappa dei collaboratori di OpenStreetMap (mappa e radar pioggia) e OpenTopoMap (mappe dei percorsi nell’app)</li>
          <li>Il nostro server — con «la mia posizione», anche la sua posizione arrotondata a circa 10 km, per scegliere la località giusta con quel nome; il suo dispositivo la ricorda per quella località</li>
          <li>RainViewer (radar pioggia) e unpkg (la libreria delle mappe) — il suo browser li carica direttamente all’apertura di una mappa, quindi vedono il suo indirizzo IP e, per il radar, l’area della mappa</li>
          <li>Apple (APNs) e Google (FCM) — recapitano le notifiche: ricevono il token push del suo telefono e il testo dell’avviso — entrambi negli USA; Apple e Google sono certificati ai sensi dell’EU-US Data Privacy Framework, quindi il trasferimento si fonda sulla decisione di adeguatezza della Commissione europea (art. 45 GDPR)</li>
          <li>ImprovMX e Google (Gmail) — inoltrano e conservano le e-mail inviate a info@metablend.app — ImprovMX riceve nell’UE (Francia) e inoltra in parte tramite server negli USA; Google è certificato ai sensi dell’EU-US Data Privacy Framework (art. 45 GDPR)</li>
        </ul>
        <p className="mt-2">Il database è ospitato su <strong>Supabase</strong> (regione UE, Francoforte). Ogni fornitore tratta i dati che riceve secondo la propria informativa sulla privacy.</p>
      </> },
      { title: 'Notifiche (app)', body: <>Se attiva le notifiche nell’app, salviamo il token push del suo telefono (di Apple o Google), l’hash di una chiave casuale creata dall’app, la sua città principale, quali avvisi ha attivato e l’ora del suo riepilogo mattutino, le vette e le date pianificate, lingua e unità, e un registro di ciò che abbiamo inviato negli ultimi 14 giorni. Nessun account, nessuna posizione. I telefoni che da 90 giorni non aprono l’app né ricevono avvisi vengono eliminati automaticamente, le escursioni pianificate dopo il loro giorno. I percorsi restano sul suo telefono; un percorso su cui pianifica un’escursione viene salvato con il piano per inviarne gli avvisi e cancellato con esso. Disattivare le notifiche nell’app o eliminare l’app le interrompe. La base giuridica è la fornitura del servizio che Lei ha attivato (art. 6, par. 1, lett. b GDPR).</> },
      { title: 'Iscrizione dei tester Android', body: <>Se si iscrive nella pagina dei tester per provare l’app Android, salviamo l’indirizzo email che inserisce e — solo se li compila — il modello del telefono e il paese, oltre alla lingua, alla data e allo stato (nuovo, aggiunto, iscritto, rimosso). L’indirizzo serve solo ad aggiungerla al test chiuso di MetaBlend su Google Play e a inviarle il link; Google la conosce quindi come tester secondo la propria informativa sulla privacy. Modello del telefono e paese ci aiutano solo a distribuire i tester tra dispositivi e regioni. Il suo indirizzo IP viene usato brevemente in memoria per prevenire abusi e non lo salviamo. La lista viene cancellata alla fine del test chiuso (al più tardi quando l’app è pubblica su Google Play), o prima su richiesta: scriva a <A href="mailto:info@metablend.app">info@metablend.app</A>. La base giuridica è il Suo consenso (art. 6, par. 1, lett. a GDPR); può revocarlo in qualsiasi momento con effetto per il futuro chiedendo la cancellazione della Sua iscrizione.</> },
      { title: 'Per quanto tempo li conserviamo', body: <>Le previsioni salvate e le righe interne di gestione vengono eliminate automaticamente da una pulizia giornaliera (di norma entro circa 48 ore); gli snapshot del consenso e i log degli errori del server dopo 30 giorni. Le segnalazioni della community restano più a lungo — alimentano la mappa pubblica della precisione e le classifiche a lungo termine — o finché non ne chiede la rimozione (vedi sotto). I pesi aggregati di precisione sono anonimi e conservati a tempo indeterminato.</> },
      { title: 'I suoi diritti e le sue scelte', body: <><p className="mb-2">Ha il diritto di accesso, rettifica, cancellazione, limitazione del trattamento, portabilità dei dati e opposizione. A tal fine scriva a <A href="mailto:info@metablend.app">info@metablend.app</A>. Può inoltre presentare reclamo all’autorità austriaca per la protezione dei dati (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Può usare l’app senza condividere la posizione, cancellare le preferenze locali in qualsiasi momento e chiedere la rimozione dei suoi dati di feedback aprendo una issue sul nostro <A href={ISSUES}>repository GitHub</A>.</p></> },
      { title: 'Contatti', body: <><p className="mb-2">Domande sulla privacy? Scriva a <A href="mailto:info@metablend.app">info@metablend.app</A> o apra una issue su <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. MetaBlend continua a evolvere; la data di «ultimo aggiornamento» in alto riflette sempre la versione corrente.</p><p>Se ci contatta via e-mail, trattiamo il suo indirizzo e-mail e il contenuto del messaggio per rispondere alla sua richiesta (art. 6, par. 1, lett. b o f GDPR). I dati vengono cancellati non appena la richiesta è evasa e non sussistono obblighi legali di conservazione.</p></> },
    ],
  },
  nl: {
    updated: 'Laatst bijgewerkt november 2026',
    t1: 'Privacy', t2: 'verklaring',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.nl}</em><br /><br />MetaBlend is een gratis weer-app in ontwikkeling <strong>zonder accounts</strong> (de enige aanmelding is de vrijwillige lijst met Android-testers). We verzamelen alleen de gegevens die nodig zijn om de dienst te laten werken en om te meten hoe nauwkeurig elke weerbron is. Dit is een samenvatting in gewone taal, geen juridisch advies.</>,
    sections: [
      { title: 'Verwerkingsverantwoordelijke', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Oostenrijk<br />E-mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Wat op uw apparaat blijft', body: <>We bewaren een paar kleine voorkeuren lokaal zodat de app uw keuzes onthoudt: taal, temperatuureenheid, weergave, de gekozen verwachtingsperiode, uw toestemming voor deze verklaring en uw recent gezochte en bewaarde steden. De laatst bekeken verwachting wordt opgeslagen zodat de app ook offline werkt. Taal, eenheid, thema, uw toestemming en recente steden staan in cookies en bereiken daardoor bij elk paginaverzoek onze server, die ze niet opslaat. Al het andere blijft in uw browser. U kunt alles altijd wissen door uw sitegegevens te wissen.</> },
      { title: 'Weerfeedback die u instuurt', body: <>Als u meldt „hoe is het weer nu”, bewaren we de stad, de temperatuur en het weertype dat u invoerde, de datum en de geschatte kaartcoördinaten van de gezochte stad (uit onze geocoder — nooit de gps-positie van uw apparaat). Dit gebruiken we om te beoordelen hoe dicht elke weerbron erbij zat, en meldingen verschijnen als punten op stadsniveau op de openbare nauwkeurigheidskaart. Het is niet gekoppeld aan uw naam, e-mail of een account, want die zijn er niet. De rechtsgrondslag is ons gerechtvaardigd belang om de nauwkeurigheid van de weerbronnen te meten en te verbeteren (art. 6 lid 1 onder f AVG).</> },
      { title: 'Technische gegevens', body: <>Om misbruik te voorkomen gebruiken we uw IP-adres kort om feedback te beperken (één melding per stad per uur). Het wordt alleen in het geheugen gebruikt voor die controle en niet samen met uw feedback opgeslagen. Mislukt een aanvraag, dan bewaart onze server het opgevraagde adres 30 dagen in het foutenlogboek, zonder de locatie van uw apparaat: niets uit „Mijn locatie”, coördinaten afgerond op ongeveer 10 km (art. 6 lid 1 onder f AVG, foutopsporing en stabiele werking).</> },
      { title: 'Hosting en serverlogbestanden', body: <>Deze website wordt gehost bij Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Bij een bezoek verwerkt Vercel technisch noodzakelijke gegevens: IP-adres, datum en tijd, opgevraagde pagina, browser- en besturingssysteeminformatie en de eerder bezochte pagina. Dit dient voor een veilige en stabiele werking (art. 6, lid 1, onder f AVG, gerechtvaardigd belang). De logbestanden worden slechts gedurende beperkte tijd bewaard en daarna verwijderd. Met Vercel is een verwerkersovereenkomst gesloten. Vercel is gecertificeerd volgens het EU-US Data Privacy Framework; de doorgifte naar de VS vindt plaats op basis van het adequaatheidsbesluit van de Europese Commissie (art. 45 AVG).</> },
      { title: 'Analyse', body: <>We gebruiken <A href={PLAUSIBLE}>Plausible Analytics</A>, een privacyvriendelijke tool die in de EU wordt gehost en bezoeken telt <strong>zonder cookies</strong> en zonder persoonsgegevens te verzamelen. We zien alleen totalen (bijv. paginaweergaven), nooit personen. Daarnaast gebruiken we <strong>Vercel Speed Insights</strong>, dat meet hoe snel pagina’s laden (anonieme prestatiecijfers zoals laadtijd), eveneens zonder cookies en zonder u te identificeren. Ook <strong>Vercel Web Analytics</strong> telt paginaweergaven zonder cookies. De rechtsgrondslag voor Plausible, Vercel Speed Insights en Vercel Web Analytics is ons gerechtvaardigd belang bij een snelle website en bij inzicht in het gebruik ervan (art. 6 lid 1 onder f AVG). Plausible verwerkt uw IP-adres alleen vluchtig, voor een dagelijks wisselend kenmerk, en slaat het niet op.</> },
      { title: 'Diensten van derden', body: <>
        <p className="mb-2">Om een verwachting te maken sturen we de stad of coördinaten die u zoekt naar weer- en geocodingdiensten, en krijgen we hun gegevens terug:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (incl. geocoding, luchtkwaliteit, historisch archief) — zoeksuggesties gaan er rechtstreeks vanuit uw browser heen, dus Open-Meteo ziet uw IP-adres</li>
          <li>Photon (komoot), OpenStreetMap en Overpass (overpass-api.de, private.coffee) — zoeken naar toppen en tophoogtes: de zoektekst en, met „In de buurt”, een locatie afgerond op ongeveer 10 km; voor gemarkeerde routes stuurt onze server alleen de coördinaten van de top</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (VS), Bright Sky (DWD), SMHI — plus ECMWF/GFS/ICON via Open-Meteo</li>
          <li>BigDataCloud — alleen als u „mijn locatie” gebruikt, om uw coördinaten om te zetten in een plaatsnaam (reverse geocoding)</li>
          <li>NOAA Aviation Weather (METAR-rapporten) en Meteostat (via RapidAPI) — krijgen op de server stadscoördinaten om referentiemetingen op te halen waarmee de nauwkeurigheid van elke bron wordt beoordeeld</li>
          <li>Kaarttegels van OpenStreetMap-bijdragers (heatmap en regenradar) en OpenTopoMap (routekaarten in de app)</li>
          <li>Onze eigen server — bij „mijn locatie” ook uw positie, afgerond op ongeveer 10 km, om de juiste plaats met die naam te kiezen; uw apparaat onthoudt die voor die plaats</li>
          <li>RainViewer (regenradar) en unpkg (de kaartbibliotheek) — uw browser laadt ze rechtstreeks zodra een kaart opent, dus ze zien uw IP-adres en, bij de radar, het kaartgebied</li>
          <li>Apple (APNs) en Google (FCM) — bezorgen meldingen: ze ontvangen de pushtoken van uw telefoon en de tekst van de melding — beide in de VS; Apple en Google zijn gecertificeerd onder het EU-VS Data Privacy Framework, zodat de doorgifte berust op het adequaatheidsbesluit van de Europese Commissie (art. 45 AVG)</li>
          <li>ImprovMX en Google (Gmail) — sturen e-mails aan info@metablend.app door en bewaren ze — ImprovMX ontvangt in de EU (Frankrijk) en stuurt deels door via servers in de VS; Google is gecertificeerd onder het EU-VS Data Privacy Framework (art. 45 AVG)</li>
        </ul>
        <p className="mt-2">De database draait bij <strong>Supabase</strong> (EU-regio, Frankfurt). Elke aanbieder verwerkt de ontvangen gegevens volgens zijn eigen privacybeleid.</p>
      </> },
      { title: 'Meldingen (app)', body: <>Als u meldingen aanzet in de app, bewaren we het pushtoken van uw telefoon (van Apple of Google), een hash van een willekeurige sleutel die de app aanmaakt, uw thuisstad, welke waarschuwingen u hebt aangezet en het uur van uw ochtendbericht, geplande toppen en dagen, uw taal en eenheid, en een logboek van wat we de afgelopen 14 dagen stuurden. Er is geen account en geen locatie. Telefoons die 90 dagen de app niet hebben geopend en geen melding hebben ontvangen, worden automatisch verwijderd, geplande tochten na hun dag. Routes blijven op uw telefoon; een route waarop u een tocht plant, wordt met het plan opgeslagen om de meldingen te sturen en samen ermee verwijderd. Meldingen uitzetten in de app of de app verwijderen stopt ze. De rechtsgrondslag is het leveren van de dienst die u hebt ingeschakeld (art. 6 lid 1 onder b AVG).</> },
      { title: 'Aanmelden als Android-tester', body: <>Als u zich op de testerspagina aanmeldt om de Android-app te testen, bewaren we het e-mailadres dat u invult en — alleen als u ze invult — uw telefoonmodel en land, plus uw taal, de datum en waar u in het proces bent (nieuw, toegevoegd, aangemeld, verwijderd). Het adres wordt alleen gebruikt om u toe te voegen aan de gesloten test van MetaBlend op Google Play en u de testlink te sturen; Google kent u dan als tester volgens zijn eigen privacybeleid. Telefoonmodel en land helpen ons alleen om testers over apparaten en regio’s te verdelen. Uw IP-adres wordt kort in het geheugen gebruikt om misbruik te voorkomen en wordt door ons niet opgeslagen. De lijst wordt verwijderd als de gesloten test afloopt (uiterlijk zodra de app openbaar is in Google Play), of eerder als u daarom vraagt: mail naar <A href="mailto:info@metablend.app">info@metablend.app</A>. De rechtsgrondslag is uw toestemming (art. 6 lid 1 onder a AVG); u kunt die op elk moment voor de toekomst intrekken door om verwijdering te vragen.</> },
      { title: 'Hoe lang we het bewaren', body: <>Opgeslagen verwachtingen en interne administratie worden automatisch verwijderd door een dagelijkse opschoning (meestal binnen ongeveer 48 uur); consensus-momentopnames en serverfoutlogs worden na 30 dagen verwijderd. Feedbackmeldingen van de community bewaren we zolang ze de openbare nauwkeurigheidskaart en de langetermijnranglijst van bronnen voeden — of tot u ons vraagt ze te verwijderen (zie hieronder). Totale nauwkeurigheidsgewichten zijn anoniem en worden onbeperkt bewaard.</> },
      { title: 'Uw rechten en keuzes', body: <><p className="mb-2">U hebt het recht op inzage, rectificatie, wissing, beperking van de verwerking, gegevensoverdraagbaarheid en bezwaar. Schrijf hiervoor naar <A href="mailto:info@metablend.app">info@metablend.app</A>. U kunt ook een klacht indienen bij de Oostenrijkse gegevensbeschermingsautoriteit (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>U kunt de app gebruiken zonder uw locatie te delen, uw lokaal opgeslagen voorkeuren altijd wissen en verwijdering van feedbackgegevens aanvragen door een issue te openen in onze <A href={ISSUES}>GitHub-repository</A>.</p></> },
      { title: 'Contact', body: <><p className="mb-2">Vragen over privacy? Mail naar <A href="mailto:info@metablend.app">info@metablend.app</A> of open een issue op <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. Naarmate MetaBlend zich ontwikkelt, kan deze verklaring veranderen; de datum „laatst bijgewerkt” hierboven geeft altijd de actuele versie aan.</p><p>Als u per e-mail contact met ons opneemt, verwerken wij uw e-mailadres en de inhoud van uw bericht om uw vraag te beantwoorden (art. 6, lid 1, onder b of f AVG). De gegevens worden verwijderd zodra de vraag is afgehandeld en er geen wettelijke bewaarplichten gelden.</p></> },
    ],
  },
  pl: {
    updated: 'Ostatnia aktualizacja: listopad 2026',
    t1: 'Polityka ', t2: 'prywatności',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.pl}</em><br /><br />MetaBlend to darmowa, rozwijana aplikacja pogodowa <strong>bez kont</strong> (jedynym zapisem jest dobrowolna lista testerów na Androida). Zbieramy tylko te dane, które są potrzebne do działania usługi i do mierzenia, jak dokładne jest każde źródło pogody. To podsumowanie prostym językiem, a nie porada prawna.</>,
    sections: [
      { title: 'Administrator danych', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Austria<br />E-mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Co zostaje na Państwa urządzeniu', body: <>Przechowujemy lokalnie kilka drobnych ustawień, aby aplikacja pamiętała Państwa wybory: język, jednostkę temperatury, wygląd, wybrany zakres prognozy, Państwa zgodę na tę politykę oraz ostatnio wyszukiwane i zapisane miasta. Ostatnio oglądana prognoza jest zapisywana, aby aplikacja działała offline. Język, jednostka, motyw, Państwa zgoda i ostatnie miasta są zapisane w plikach cookie, więc przy każdym otwarciu strony trafiają na nasz serwer, który ich nie przechowuje. Cała reszta zostaje w Państwa przeglądarce. Mogą Państwo to wszystko w każdej chwili usunąć, czyszcząc dane witryny.</> },
      { title: 'Opinie o pogodzie, które Państwo wysyłają', body: <>Gdy zgłaszają Państwo „jaka jest teraz pogoda”, zapisujemy miasto, podaną temperaturę i warunki, datę oraz przybliżone współrzędne wyszukanego miasta (z naszego geokodera — nigdy pozycję GPS Państwa urządzenia). Służy to ocenie, jak blisko prawdy było każde źródło, a zgłoszenia pojawiają się jako punkty na poziomie miast na publicznej mapie dokładności. Nie są powiązane z Państwa imieniem, e-mailem ani kontem, bo takich nie ma. Podstawą prawną jest nasz prawnie uzasadniony interes w mierzeniu i poprawianiu dokładności źródeł pogodowych (art. 6 ust. 1 lit. f RODO).</> },
      { title: 'Dane techniczne', body: <>Aby zapobiegać nadużyciom, na krótko używamy Państwa adresu IP do ograniczania opinii (jedno zgłoszenie na miasto na godzinę). Jest on używany w pamięci tylko do tego sprawdzenia i nie jest zapisywany razem z opinią. Jeśli żądanie się nie powiedzie, nasz serwer zachowuje wywołany adres przez 30 dni w dzienniku błędów, bez lokalizacji Państwa urządzenia: nic z „Moja lokalizacja”, a współrzędne są zaokrąglone do około 10 km (art. 6 ust. 1 lit. f RODO, usuwanie błędów i stabilne działanie).</> },
      { title: 'Hosting i logi serwera', body: <>Ta strona jest hostowana przez Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Podczas wizyty Vercel przetwarza dane niezbędne technicznie: adres IP, datę i godzinę, otwartą stronę, informacje o przeglądarce i systemie operacyjnym oraz poprzednio odwiedzoną stronę. Służy to bezpiecznemu i stabilnemu działaniu (art. 6 ust. 1 lit. f RODO, prawnie uzasadniony interes). Pliki logów są przechowywane tylko przez ograniczony czas, a następnie usuwane. Z Vercel zawarta jest umowa powierzenia przetwarzania danych. Vercel posiada certyfikację zgodnie z EU-US Data Privacy Framework; przekazywanie danych do USA odbywa się na podstawie decyzji Komisji Europejskiej stwierdzającej odpowiedni stopień ochrony (art. 45 RODO).</> },
      { title: 'Analityka', body: <>Korzystamy z <A href={PLAUSIBLE}>Plausible Analytics</A>, przyjaznego prywatności narzędzia hostowanego w UE, które liczy wizyty <strong>bez plików cookie</strong> i bez zbierania danych osobowych. Widzimy tylko liczby zbiorcze (np. odsłony), nigdy pojedyncze osoby. Używamy też <strong>Vercel Speed Insights</strong>, które mierzy szybkość ładowania stron (anonimowe dane o wydajności, np. czas ładowania), również bez plików cookie i bez identyfikowania Państwa. <strong>Vercel Web Analytics</strong> również zlicza odsłony bez plików cookie. Podstawą prawną dla Plausible, Vercel Speed Insights i Vercel Web Analytics jest nasz prawnie uzasadniony interes w szybkiej stronie i wiedzy o tym, jak jest używana (art. 6 ust. 1 lit. f RODO). Plausible przetwarza Państwa adres IP tylko przelotnie, na potrzeby zmieniającego się codziennie identyfikatora, i go nie zapisuje.</> },
      { title: 'Usługi zewnętrzne', body: <>
        <p className="mb-2">Aby przygotować prognozę, wysyłamy wyszukiwane miasto lub współrzędne do dostawców danych pogodowych i geokodowania, a oni odsyłają nam swoje dane:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (w tym geokodowanie, jakość powietrza, archiwum historyczne) — podpowiedzi wyszukiwania trafiają tam bezpośrednio z Państwa przeglądarki, więc Open-Meteo widzi Państwa adres IP</li>
          <li>Photon (komoot), OpenStreetMap i Overpass (overpass-api.de, private.coffee) — wyszukiwanie szczytów i ich wysokości: wyszukiwany tekst oraz, przy „W pobliżu”, lokalizacja zaokrąglona do ok. 10 km; dla oznakowanych tras nasz serwer wysyła tylko współrzędne szczytu</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (USA), Bright Sky (DWD), SMHI — oraz ECMWF/GFS/ICON przez Open-Meteo</li>
          <li>BigDataCloud — tylko gdy używają Państwo „mojej lokalizacji”, aby zamienić współrzędne na nazwę miasta (odwrotne geokodowanie)</li>
          <li>NOAA Aviation Weather (raporty METAR) i Meteostat (przez RapidAPI) — otrzymują po stronie serwera współrzędne miast, aby pobrać pomiary referencyjne do oceny dokładności źródeł</li>
          <li>Kafelki map od współtwórców OpenStreetMap (mapa cieplna i radar opadów) oraz OpenTopoMap (mapy tras w aplikacji)</li>
          <li>Nasz własny serwer — przy „mojej lokalizacji” także Państwa pozycja zaokrąglona do około 10 km, aby wybrać właściwą miejscowość o tej nazwie; Państwa urządzenie zapamiętuje ją dla tej miejscowości</li>
          <li>RainViewer (radar opadów) i unpkg (biblioteka map) — Państwa przeglądarka ładuje je bezpośrednio po otwarciu mapy, więc widzą Państwa adres IP, a w przypadku radaru także obszar mapy</li>
          <li>Apple (APNs) i Google (FCM) — dostarczają powiadomienia: otrzymują token push Państwa telefonu i treść powiadomienia — oba w USA; Apple i Google są certyfikowane w ramach EU-US Data Privacy Framework, więc przekazanie opiera się na decyzji Komisji Europejskiej stwierdzającej odpowiedni stopień ochrony (art. 45 RODO)</li>
          <li>ImprovMX i Google (Gmail) — przekazują i przechowują e-maile wysyłane na info@metablend.app — ImprovMX odbiera w UE (Francja) i przekazuje częściowo przez serwery w USA; Google jest certyfikowany w ramach EU-US Data Privacy Framework (art. 45 RODO)</li>
        </ul>
        <p className="mt-2">Baza danych działa w <strong>Supabase</strong> (region UE, Frankfurt). Każdy dostawca przetwarza otrzymane dane zgodnie z własną polityką prywatności.</p>
      </> },
      { title: 'Powiadomienia (aplikacja)', body: <>Jeśli włączą Państwo powiadomienia w aplikacji, zapisujemy token push Państwa telefonu (od Apple lub Google), skrót losowego klucza tworzonego przez aplikację, Państwa miasto domowe, włączone ostrzeżenia i godzinę porannego przeglądu, zaplanowane szczyty i dni, język i jednostkę oraz dziennik tego, co wysłaliśmy w ostatnich 14 dniach. Nie ma konta ani lokalizacji. Telefony, które przez 90 dni nie otworzyły aplikacji ani nie otrzymały powiadomienia, są usuwane automatycznie, a zaplanowane wędrówki po ich dniu. Trasy zostają na Państwa telefonie; trasa, na której planują Państwo wędrówkę, jest zapisywana razem z planem, aby wysłać jej powiadomienia, i usuwana wraz z nim. Wyłączenie powiadomień w aplikacji lub jej usunięcie je zatrzymuje. Podstawą prawną jest świadczenie usługi, którą Państwo włączyli (art. 6 ust. 1 lit. b RODO).</> },
      { title: 'Zapisy testerów na Androida', body: <>Jeśli zapiszą się Państwo na stronie testerów, aby testować aplikację na Androida, przechowujemy podany adres e-mail i — tylko jeśli je Państwo wypełnią — model telefonu i kraj, a także język, datę i etap (nowy, dodany, dołączył, usunięty). Adres służy wyłącznie do dodania Państwa do zamkniętego testu MetaBlend w Google Play i wysłania linku testowego; Google zna Państwa wtedy jako testera zgodnie z własną polityką prywatności. Model telefonu i kraj pomagają nam jedynie rozłożyć testerów na różne urządzenia i regiony. Państwa adres IP jest krótko używany w pamięci, aby zapobiegać nadużyciom, i nie zapisujemy go. Lista jest usuwana po zakończeniu testu zamkniętego (najpóźniej, gdy aplikacja będzie publicznie dostępna w Google Play) lub wcześniej na prośbę: prosimy pisać na <A href="mailto:info@metablend.app">info@metablend.app</A>. Podstawą prawną jest Państwa zgoda (art. 6 ust. 1 lit. a RODO); mogą ją Państwo w każdej chwili wycofać ze skutkiem na przyszłość, prosząc o usunięcie wpisu.</> },
      { title: 'Jak długo przechowujemy dane', body: <>Zapisane prognozy i wewnętrzne wpisy porządkowe są automatycznie usuwane przez codzienne czyszczenie (zwykle w ciągu ok. 48 godzin); migawki konsensusu i logi błędów serwera są usuwane po 30 dniach. Opinie społeczności przechowujemy tak długo, jak zasilają publiczną mapę dokładności i długoterminowe rankingi źródeł — lub do czasu, aż poproszą Państwo o ich usunięcie (patrz niżej). Zbiorcze wagi dokładności są anonimowe i przechowywane bezterminowo.</> },
      { title: 'Państwa prawa i wybory', body: <><p className="mb-2">Przysługuje Państwu prawo dostępu, sprostowania, usunięcia, ograniczenia przetwarzania, przenoszenia danych i sprzeciwu. W tym celu prosimy pisać na <A href="mailto:info@metablend.app">info@metablend.app</A>. Mogą Państwo również złożyć skargę do austriackiego organu ochrony danych (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Mogą Państwo korzystać z aplikacji bez udostępniania lokalizacji, w każdej chwili usunąć lokalnie zapisane ustawienia i poprosić o usunięcie danych z opinii, zgłaszając sprawę w naszym <A href={ISSUES}>repozytorium GitHub</A>.</p></> },
      { title: 'Kontakt', body: <><p className="mb-2">Pytania o prywatność? Prosimy pisać na <A href="mailto:info@metablend.app">info@metablend.app</A> lub zgłosić sprawę na <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. W miarę rozwoju MetaBlend ta polityka może się zmieniać; data „ostatniej aktualizacji” powyżej zawsze wskazuje aktualną wersję.</p><p>Jeśli kontaktują się Państwo z nami e-mailem, przetwarzamy Państwa adres e-mail i treść wiadomości, aby odpowiedzieć na zapytanie (art. 6 ust. 1 lit. b lub f RODO). Dane są usuwane po załatwieniu sprawy, o ile nie obowiązują ustawowe obowiązki przechowywania.</p></> },
    ],
  },
  cs: {
    updated: 'Naposledy aktualizováno v listopadu 2026',
    t1: 'Ochrana ', t2: 'soukromí',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.cs}</em><br /><br />MetaBlend je bezplatná aplikace o počasí ve vývoji <strong>bez účtů</strong> (jedinou registrací je dobrovolný seznam testerů pro Android). Sbíráme jen data nezbytná pro provoz služby a pro měření přesnosti jednotlivých zdrojů počasí. Toto je shrnutí srozumitelným jazykem, nikoli právní rada.</>,
    sections: [
      { title: 'Správce údajů', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Rakousko<br />E-mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Co zůstává ve vašem zařízení', body: <>Lokálně ukládáme několik drobných nastavení, aby si aplikace pamatovala vaše volby: jazyk, jednotku teploty, vzhled, zvolený rozsah předpovědi, váš souhlas s tímto oznámením a nedávno hledaná a uložená města. Naposledy zobrazená předpověď se ukládá, aby aplikace fungovala i offline. Jazyk, jednotka, motiv, váš souhlas a nedávná města jsou uložené v cookies, takže se při každém načtení stránky dostanou na náš server, který je neukládá. Vše ostatní zůstává ve vašem prohlížeči. Kdykoli to všechno smažete vymazáním dat webu.</> },
      { title: 'Zpětná vazba k počasí, kterou odešlete', body: <>Když nahlásíte „jaké je teď počasí“, uložíme město, zadanou teplotu a stav, datum a přibližné souřadnice hledaného města (z našeho geokodéru — nikdy polohu GPS vašeho zařízení). Slouží to k hodnocení, jak blízko byl každý zdroj, a hlášení se zobrazují jako body na úrovni měst na veřejné mapě přesnosti. Nejsou spojena s vaším jménem, e-mailem ani účtem, protože žádné nejsou. Právním základem je náš oprávněný zájem měřit a zlepšovat přesnost zdrojů počasí (čl. 6 odst. 1 písm. f GDPR).</> },
      { title: 'Technická data', body: <>Abychom zabránili zneužití, krátce používáme vaši IP adresu k omezení zpětné vazby (jedno hlášení na město za hodinu). Používá se jen v paměti pro tuto kontrolu a neukládá se spolu se zpětnou vazbou. Selže-li požadavek, uchová náš server volanou adresu 30 dní v protokolu chyb, bez polohy Vašeho zařízení: nic z „Moje poloha“, souřadnice zaokrouhlené na přibližně 10 km (čl. 6 odst. 1 písm. f GDPR, odstraňování chyb a stabilní provoz).</> },
      { title: 'Hosting a serverové logy', body: <>Tento web je hostován u společnosti Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Při návštěvě zpracovává Vercel technicky nezbytné údaje: IP adresu, datum a čas, vyvolanou stránku, informace o prohlížeči a operačním systému a dříve navštívenou stránku. Slouží to k bezpečnému a stabilnímu provozu (čl. 6 odst. 1 písm. f GDPR, oprávněný zájem). Logy se uchovávají jen po omezenou dobu a poté se mažou. S Vercel je uzavřena smlouva o zpracování osobních údajů. Vercel je certifikován podle EU-US Data Privacy Framework; předávání do USA probíhá na základě rozhodnutí Evropské komise o odpovídající ochraně (čl. 45 GDPR).</> },
      { title: 'Analytika', body: <>Používáme <A href={PLAUSIBLE}>Plausible Analytics</A>, nástroj šetrný k soukromí hostovaný v EU, který počítá návštěvy <strong>bez souborů cookie</strong> a bez sběru osobních údajů. Vidíme jen souhrnná čísla (např. zobrazení stránek), nikdy jednotlivce. Používáme také <strong>Vercel Speed Insights</strong>, které měří, jak rychle se stránky načítají (anonymní údaje o výkonu, např. dobu načtení), rovněž bez cookie a bez vaší identifikace. Také <strong>Vercel Web Analytics</strong> počítá zobrazení stránek bez cookie. Právním základem pro Plausible, Vercel Speed Insights a Vercel Web Analytics je náš oprávněný zájem na rychlém webu a na znalosti toho, jak je používán (čl. 6 odst. 1 písm. f GDPR). Plausible zpracovává Vaši IP adresu jen pomíjivě, pro denně se měnící identifikátor, a neukládá ji.</> },
      { title: 'Služby třetích stran', body: <>
        <p className="mb-2">Pro sestavení předpovědi posíláme hledané město nebo souřadnice poskytovatelům dat o počasí a geokódování a dostáváme zpět jejich data:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (vč. geokódování, kvality ovzduší, historického archivu) — návrhy hledání tam jdou přímo z vašeho prohlížeče, takže Open-Meteo vidí vaši IP adresu</li>
          <li>Photon (komoot), OpenStreetMap a Overpass (overpass-api.de, private.coffee) — hledání vrcholů a jejich výšek: hledaný text a u „Poblíž“ poloha zaokrouhlená asi na 10 km; pro značené trasy náš server posílá jen souřadnice vrcholu</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (USA), Bright Sky (DWD), SMHI — a ECMWF/GFS/ICON přes Open-Meteo</li>
          <li>BigDataCloud — jen pokud použijete „moji polohu“, k převodu souřadnic na název města (reverzní geokódování)</li>
          <li>NOAA Aviation Weather (hlášení METAR) a Meteostat (přes RapidAPI) — dostávají na serveru souřadnice měst, aby získaly referenční měření pro hodnocení přesnosti zdrojů</li>
          <li>Mapové dlaždice od přispěvatelů OpenStreetMap (teplotní mapa a srážkový radar) a OpenTopoMap (mapy tras v aplikaci)</li>
          <li>Náš vlastní server — při „Moje poloha“ také vaše poloha zaokrouhlená na přibližně 10 km, aby se vybralo správné místo tohoto názvu; vaše zařízení si ji pro toto místo pamatuje</li>
          <li>RainViewer (srážkový radar) a unpkg (knihovna map) — váš prohlížeč je načítá přímo při otevření mapy, takže vidí vaši IP adresu a u radaru i oblast mapy</li>
          <li>Apple (APNs) a Google (FCM) — doručují oznámení: dostávají push token vašeho telefonu a text oznámení — oba v USA; Apple a Google jsou certifikovány podle EU-US Data Privacy Framework, předání se tedy opírá o rozhodnutí Evropské komise o odpovídající ochraně (čl. 45 GDPR)</li>
          <li>ImprovMX a Google (Gmail) — přeposílají a ukládají e-maily zaslané na info@metablend.app — ImprovMX přijímá v EU (Francie) a přeposílá zčásti přes servery v USA; Google je certifikován podle EU-US Data Privacy Framework (čl. 45 GDPR)</li>
        </ul>
        <p className="mt-2">Databáze běží na <strong>Supabase</strong> (region EU, Frankfurt). Každý poskytovatel zpracovává data, která obdrží, podle vlastních zásad ochrany soukromí.</p>
      </> },
      { title: 'Oznámení (aplikace)', body: <>Pokud v aplikaci zapnete oznámení, uložíme push token vašeho telefonu (od Apple nebo Google), hash náhodného klíče, který aplikace vytvoří, vaše domovské město, zapnutá upozornění a hodinu ranního přehledu, plánované vrcholy a dny, jazyk a jednotku a záznam toho, co jsme odeslali za posledních 14 dní. Neexistuje účet ani poloha. Telefony, které 90 dní neotevřely aplikaci ani nedostaly oznámení, se automaticky mažou, plánované túry po jejich dni. Trasy zůstávají ve vašem telefonu; trasa, na které plánujete túru, se uloží s plánem kvůli odeslání upozornění a smaže se spolu s ním. Vypnutím oznámení v aplikaci nebo smazáním aplikace je zastavíte. Právním základem je poskytování služby, kterou jste zapnuli (čl. 6 odst. 1 písm. b GDPR).</> },
      { title: 'Přihláška testerů pro Android', body: <>Pokud se na stránce pro testery přihlásíte k testování aplikace pro Android, uložíme zadanou e-mailovou adresu a — jen pokud je vyplníte — model telefonu a zemi, dále jazyk, datum a fázi (nový, přidán, připojen, odebrán). Adresa slouží jen k přidání do uzavřeného testu MetaBlend na Google Play a k zaslání testovacího odkazu; Google vás pak zná jako testera podle svých vlastních zásad ochrany soukromí. Model telefonu a země nám jen pomáhají rozložit testery mezi zařízení a regiony. Vaši IP adresu krátce používáme v paměti proti zneužití a neukládáme ji. Seznam se smaže po skončení uzavřeného testu (nejpozději, až bude aplikace veřejně na Google Play), nebo dříve na požádání: napište na <A href="mailto:info@metablend.app">info@metablend.app</A>. Právním základem je Váš souhlas (čl. 6 odst. 1 písm. a GDPR); můžete jej kdykoli s účinky do budoucna odvolat tím, že požádáte o výmaz.</> },
      { title: 'Jak dlouho data uchováváme', body: <>Uložené předpovědi a interní evidenční záznamy maže automaticky denní úklid (obvykle do zhruba 48 hodin); snímky konsenzu a chybové logy serveru se mažou po 30 dnech. Zpětnou vazbu komunity uchováváme, dokud slouží veřejné mapě přesnosti a dlouhodobému žebříčku zdrojů — nebo dokud nás nepožádáte o její odstranění (viz níže). Souhrnné váhy přesnosti jsou anonymní a uchovávají se natrvalo.</> },
      { title: 'Vaše práva a volby', body: <><p className="mb-2">Máte právo na přístup, opravu, výmaz, omezení zpracování, přenositelnost údajů a námitku. Napište nám na <A href="mailto:info@metablend.app">info@metablend.app</A>. Můžete také podat stížnost u rakouského úřadu pro ochranu osobních údajů (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Aplikaci můžete používat bez sdílení polohy, kdykoli smazat lokálně uložená nastavení a požádat o odstranění dat zpětné vazby otevřením issue v našem <A href={ISSUES}>repozitáři na GitHubu</A>.</p></> },
      { title: 'Kontakt', body: <><p className="mb-2">Otázky k soukromí? Napište na <A href="mailto:info@metablend.app">info@metablend.app</A> nebo otevřete issue na <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. S vývojem MetaBlend se toto oznámení může měnit; datum „naposledy aktualizováno“ výše vždy odpovídá aktuální verzi.</p><p>Pokud nás kontaktujete e-mailem, zpracováváme vaši e-mailovou adresu a obsah vaší zprávy, abychom odpověděli na váš dotaz (čl. 6 odst. 1 písm. b nebo f GDPR). Údaje se smažou, jakmile je dotaz vyřízen a nebrání tomu zákonné povinnosti uchovávání.</p></> },
    ],
  },
  sl: {
    updated: 'Zadnja posodobitev: november 2026',
    t1: 'Varstvo ', t2: 'zasebnosti',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.sl}</em><br /><br />MetaBlend je brezplačna vremenska aplikacija v razvoju <strong>brez računov</strong> (edina prijava je neobvezen seznam preizkuševalcev za Android). Zbiramo le podatke, ki so potrebni za delovanje storitve in za merjenje natančnosti posameznih vremenskih virov. To je povzetek v preprostem jeziku, ne pravni nasvet.</>,
    sections: [
      { title: 'Upravljavec', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Avstrija<br />E-pošta: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'Kaj ostane na vaši napravi', body: <>Lokalno shranimo nekaj majhnih nastavitev, da si aplikacija zapomni vaše izbire: jezik, enoto temperature, videz, izbrano obdobje napovedi, vašo privolitev v to obvestilo ter nedavno iskana in shranjena mesta. Zadnja ogledana napoved se shrani, da aplikacija deluje tudi brez povezave. Jezik, enota, tema, vaše soglasje in nedavna mesta so shranjeni v piškotkih, zato ob vsakem nalaganju strani pridejo do našega strežnika, ki jih ne shranjuje. Vse drugo ostane v vašem brskalniku. Vse lahko kadarkoli izbrišete z brisanjem podatkov spletnega mesta.</> },
      { title: 'Vremenski odzivi, ki jih pošljete', body: <>Ko sporočite »kakšno je vreme zdaj«, shranimo mesto, vneseno temperaturo in stanje, datum in približne koordinate iskanega mesta (iz našega geokoderja — nikoli položaja GPS vaše naprave). To uporabimo za oceno, kako blizu je bil posamezen vir, poročila pa se prikažejo kot točke na ravni mest na javnem zemljevidu natančnosti. Niso povezana z vašim imenom, e-pošto ali računom, ker teh ni. Pravna podlaga je naš zakoniti interes, da merimo in izboljšujemo natančnost vremenskih virov (člen 6(1)(f) GDPR).</> },
      { title: 'Tehnični podatki', body: <>Da preprečimo zlorabe, za kratek čas uporabimo vaš naslov IP za omejevanje odzivov (eno poročilo na mesto na uro). Uporablja se le v pomnilniku za to preverjanje in se ne shrani skupaj z odzivom. Če zahteva ne uspe, naš strežnik 30 dni hrani klicani naslov v dnevniku napak, brez lokacije vaše naprave: nič iz »Moja lokacija«, koordinate so zaokrožene na približno 10 km (člen 6(1)(f) GDPR, odpravljanje napak in stabilno delovanje).</> },
      { title: 'Gostovanje in strežniški dnevniki', body: <>To spletno mesto gostuje pri Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Ob obisku Vercel obdeluje tehnično potrebne podatke: naslov IP, datum in čas, odprto stran, podatke o brskalniku in operacijskem sistemu ter predhodno obiskano stran. To je namenjeno varnemu in stabilnemu delovanju (člen 6(1)(f) GDPR, zakoniti interes). Dnevniške datoteke se hranijo le omejen čas in se nato izbrišejo. Z Vercel je sklenjena pogodba o obdelavi osebnih podatkov. Vercel je certificiran v skladu z EU-US Data Privacy Framework; prenos v ZDA temelji na sklepu Evropske komisije o ustreznosti (člen 45 GDPR).</> },
      { title: 'Analitika', body: <>Uporabljamo <A href={PLAUSIBLE}>Plausible Analytics</A>, zasebnosti prijazno orodje, gostovano v EU, ki šteje obiske <strong>brez piškotkov</strong> in brez zbiranja osebnih podatkov. Vidimo le skupne številke (npr. oglede strani), nikoli posameznikov. Uporabljamo tudi <strong>Vercel Speed Insights</strong>, ki meri, kako hitro se strani naložijo (anonimni podatki o zmogljivosti, npr. čas nalaganja), prav tako brez piškotkov in brez vaše identifikacije. Tudi <strong>Vercel Web Analytics</strong> šteje oglede strani brez piškotkov. Pravna podlaga za Plausible, Vercel Speed Insights in Vercel Web Analytics je naš zakoniti interes za hitro spletno mesto in za vedenje, kako se uporablja (člen 6(1)(f) GDPR). Plausible vaš naslov IP obdela le bežno, za dnevno spreminjajoč se identifikator, in ga ne shrani.</> },
      { title: 'Storitve tretjih oseb', body: <>
        <p className="mb-2">Za pripravo napovedi pošljemo iskano mesto ali koordinate ponudnikom vremenskih podatkov in geokodiranja ter od njih prejmemo podatke:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (vklj. geokodiranje, kakovost zraka, zgodovinski arhiv) — predlogi iskanja gredo tja neposredno iz vašega brskalnika, zato Open-Meteo vidi vaš naslov IP</li>
          <li>Photon (komoot), OpenStreetMap in Overpass (overpass-api.de, private.coffee) — iskanje vrhov in njihovih višin: iskano besedilo in pri »V bližini« lokacija, zaokrožena na približno 10 km; za označene poti naš strežnik pošlje le koordinate vrha</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (ZDA), Bright Sky (DWD), SMHI — ter ECMWF/GFS/ICON prek Open-Meteo</li>
          <li>BigDataCloud — le če uporabite »mojo lokacijo«, da koordinate pretvori v ime mesta (obratno geokodiranje)</li>
          <li>NOAA Aviation Weather (poročila METAR) in Meteostat (prek RapidAPI) — na strežniku prejmeta koordinate mest, da pridobita referenčne meritve za oceno natančnosti virov</li>
          <li>Ploščice zemljevidov sodelavcev OpenStreetMap (toplotni zemljevid in radar padavin) ter OpenTopoMap (zemljevidi poti v aplikaciji)</li>
          <li>Naš lastni strežnik — pri »Moja lokacija« tudi vaš položaj, zaokrožen na približno 10 km, da izberemo pravi kraj s tem imenom; vaša naprava si ga za ta kraj zapomni</li>
          <li>RainViewer (radar padavin) in unpkg (knjižnica zemljevidov) — vaš brskalnik ju naloži neposredno ob odprtju zemljevida, zato vidita vaš naslov IP, pri radarju pa tudi območje zemljevida</li>
          <li>Apple (APNs) in Google (FCM) — dostavljata obvestila: prejmeta žeton push vašega telefona in besedilo obvestila — oba v ZDA; Apple in Google sta certificirana po okviru EU-ZDA o zasebnosti podatkov, zato prenos temelji na sklepu Evropske komisije o ustreznosti (člen 45 GDPR)</li>
          <li>ImprovMX in Google (Gmail) — posredujeta in hranita e-pošto, poslano na info@metablend.app — ImprovMX sprejema v EU (Francija) in deloma posreduje prek strežnikov v ZDA; Google je certificiran po okviru EU-ZDA o zasebnosti podatkov (člen 45 GDPR)</li>
        </ul>
        <p className="mt-2">Podatkovna baza teče pri <strong>Supabase</strong> (regija EU, Frankfurt). Vsak ponudnik obdeluje prejete podatke po svoji politiki zasebnosti.</p>
      </> },
      { title: 'Obvestila (aplikacija)', body: <>Če v aplikaciji vklopite obvestila, shranimo potisni žeton vašega telefona (od Apple ali Google), zgoščeno vrednost naključnega ključa, ki ga ustvari aplikacija, vaš domači kraj, vklopljena opozorila in uro jutranjega pregleda, načrtovane vrhove in dneve, jezik in enoto ter dnevnik poslanega v zadnjih 14 dneh. Ni računa in ni lokacije. Telefoni, ki 90 dni niso odprli aplikacije niti prejeli obvestila, se samodejno izbrišejo, načrtovane ture pa po njihovem dnevu. Poti ostanejo na vašem telefonu; pot, na kateri načrtujete turo, se shrani z načrtom za pošiljanje obvestil in se izbriše skupaj z njim. Izklop obvestil v aplikaciji ali izbris aplikacije jih ustavi. Pravna podlaga je zagotavljanje storitve, ki ste jo vklopili (člen 6(1)(b) GDPR).</> },
      { title: 'Prijava preizkuševalcev za Android', body: <>Če se na strani za preizkuševalce prijavite za preizkus aplikacije za Android, shranimo vpisani e-poštni naslov in — samo če ju vpišete — model telefona in državo, poleg tega jezik, datum in fazo (nov, dodan, pridružen, odstranjen). Naslov uporabimo samo za to, da vas dodamo v zaprti preizkus MetaBlend v Google Play in vam pošljemo povezavo; Google vas nato pozna kot preizkuševalca po svojem pravilniku o zasebnosti. Model telefona in država nam pomagata le razporediti preizkuševalce med naprave in regije. Vaš naslov IP na kratko uporabimo v pomnilniku za preprečevanje zlorab in ga ne shranimo. Seznam izbrišemo, ko se zaprti preizkus konča (najpozneje, ko je aplikacija javno na voljo v Google Play), ali prej na vašo zahtevo: pišite na <A href="mailto:info@metablend.app">info@metablend.app</A>. Pravna podlaga je vaša privolitev (člen 6(1)(a) GDPR); kadar koli jo lahko z učinkom za naprej prekličete tako, da zahtevate izbris.</> },
      { title: 'Kako dolgo hranimo podatke', body: <>Shranjene napovedi in notranje evidenčne vrstice samodejno izbriše dnevno čiščenje (običajno v približno 48 urah); posnetki soglasja in dnevniki napak strežnika se izbrišejo po 30 dneh. Odzive skupnosti hranimo, dokler poganjajo javni zemljevid natančnosti in dolgoročno lestvico virov — ali dokler nas ne prosite za izbris (glej spodaj). Skupne uteži natančnosti so anonimne in se hranijo trajno.</> },
      { title: 'Vaše pravice in izbire', body: <><p className="mb-2">Imate pravico do dostopa, popravka, izbrisa, omejitve obdelave, prenosljivosti podatkov in ugovora. Za to pišite na <A href="mailto:info@metablend.app">info@metablend.app</A>. Pritožbo lahko vložite tudi pri avstrijskem organu za varstvo podatkov (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Aplikacijo lahko uporabljate brez deljenja lokacije, kadarkoli izbrišete lokalno shranjene nastavitve in zahtevate izbris podatkov odzivov z odprtjem zadeve v našem <A href={ISSUES}>repozitoriju GitHub</A>.</p></> },
      { title: 'Stik', body: <><p className="mb-2">Vprašanja o zasebnosti? Pišite na <A href="mailto:info@metablend.app">info@metablend.app</A> ali odprite zadevo na <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. Z razvojem MetaBlend se to obvestilo lahko spremeni; datum »zadnja posodobitev« zgoraj vedno ustreza trenutni različici.</p><p>Če nas kontaktirate po e-pošti, obdelujemo vaš e-poštni naslov in vsebino sporočila, da odgovorimo na vaše vprašanje (člen 6(1)(b) oziroma (f) GDPR). Podatki se izbrišejo, ko je vprašanje rešeno in ne veljajo zakonske obveznosti hrambe.</p></> },
    ],
  },
  pt: {
    updated: 'Última atualização: novembro de 2026',
    t1: 'Aviso de ', t2: 'privacidade',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.pt}</em><br /><br />O MetaBlend é um app de previsão do tempo gratuito, em desenvolvimento, <strong>sem contas</strong> (a única inscrição é a lista opcional de testadores do Android). Coletamos apenas os dados necessários para o serviço funcionar e para medir o quão precisa é cada fonte meteorológica. Este é um resumo em linguagem simples, não uma orientação jurídica.</>,
    sections: [
      { title: 'Controlador', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, Áustria<br />E-mail: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: 'O que fica no seu dispositivo', body: <>Guardamos algumas pequenas preferências localmente para o app lembrar suas escolhas: idioma, unidade de temperatura, aparência, o período de previsão escolhido, seu consentimento a este aviso e as cidades buscadas e salvas recentemente. A última previsão vista fica armazenada para o app funcionar offline. Idioma, unidade, tema, seu consentimento e cidades recentes ficam em cookies e, por isso, chegam ao nosso servidor a cada carregamento de página; ele não os armazena. Todo o resto fica no seu navegador. Você pode apagar tudo a qualquer momento limpando os dados do site.</> },
      { title: 'Retornos sobre o tempo que você envia', body: <>Quando você informa “como está o tempo agora”, guardamos a cidade, a temperatura e a condição que você inseriu, a data e as coordenadas aproximadas da cidade buscada (do nosso geocodificador — nunca a posição de GPS do seu dispositivo). Isso serve para avaliar o quanto cada fonte acertou, e os relatos aparecem como pontos por cidade no mapa público de precisão. Eles não são ligados ao seu nome, e-mail ou conta, porque não existem. A base jurídica é o nosso interesse legítimo em medir e melhorar a precisão das fontes meteorológicas (art. 6(1)(f) do RGPD).</> },
      { title: 'Dados técnicos', body: <>Para evitar abusos, usamos seu endereço IP por um breve momento para limitar os retornos (um relato por cidade por hora). Ele é usado apenas na memória para essa verificação e não é armazenado junto com o retorno. Se uma solicitação falhar, nosso servidor guarda o endereço solicitado por 30 dias no registro de erros, sem a localização do seu dispositivo: nada de “Minha localização” e coordenadas arredondadas para cerca de 10 km (art. 6(1)(f) do RGPD, correção de erros e funcionamento estável).</> },
      { title: 'Hospedagem e arquivos de log do servidor', body: <>Este site é hospedado pela Vercel Inc. (440 N Barranca Ave #4133, Covina, CA 91723, USA). Ao acessá-lo, a Vercel processa dados tecnicamente necessários: endereço IP, data e hora, página acessada, informações do navegador e do sistema operacional e a página visitada anteriormente. Isso serve à operação segura e estável (art. 6.º, n.º 1, al. f do RGPD, interesse legítimo). Os arquivos de log são armazenados apenas por tempo limitado e depois excluídos. Existe um contrato de tratamento de dados com a Vercel. A Vercel é certificada pelo EU-US Data Privacy Framework; a transferência para os EUA ocorre com base na decisão de adequação da Comissão Europeia (art. 45.º do RGPD).</> },
      { title: 'Análises', body: <>Usamos o <A href={PLAUSIBLE}>Plausible Analytics</A>, uma ferramenta que respeita a privacidade, hospedada na UE, que conta visitas <strong>sem cookies</strong> e sem coletar dados pessoais. Vemos apenas números agregados (ex.: visualizações de página), nunca pessoas. Também usamos o <strong>Vercel Speed Insights</strong>, que mede a velocidade de carregamento das páginas (números anônimos de desempenho, como tempo de carregamento), também sem cookies e sem identificar você. O <strong>Vercel Web Analytics</strong> também conta visualizações de página sem cookies. A base jurídica para Plausible, Vercel Speed Insights e Vercel Web Analytics é nosso interesse legítimo em um site rápido e em saber como ele é usado (art. 6(1)(f) do RGPD). O Plausible trata seu endereço IP apenas de forma passageira, para um identificador que muda diariamente, e não o armazena.</> },
      { title: 'Serviços de terceiros', body: <>
        <p className="mb-2">Para gerar uma previsão, enviamos a cidade ou as coordenadas que você busca a provedores de dados meteorológicos e de geocodificação e recebemos os dados deles:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo (incl. geocodificação, qualidade do ar, arquivo histórico) — as sugestões de busca vão direto do seu navegador para lá, então o Open-Meteo vê seu endereço IP</li>
          <li>Photon (komoot), OpenStreetMap e Overpass (overpass-api.de, private.coffee) — busca de picos e altitudes: o texto buscado e, com “Perto de mim”, uma localização arredondada a cerca de 10 km; para rotas sinalizadas, nosso servidor envia apenas as coordenadas do cume</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS (EUA), Bright Sky (DWD), SMHI — além de ECMWF/GFS/ICON via Open-Meteo</li>
          <li>BigDataCloud — só se você usar “minha localização”, para transformar suas coordenadas no nome de uma cidade (geocodificação reversa)</li>
          <li>NOAA Aviation Weather (boletins METAR) e Meteostat (via RapidAPI) — recebem no servidor as coordenadas das cidades para obter medições de referência que avaliam a precisão de cada fonte</li>
          <li>Blocos de mapa dos colaboradores do OpenStreetMap (mapa de calor e radar de chuva) e OpenTopoMap (mapas de rotas no app)</li>
          <li>Nosso próprio servidor — com “minha localização”, também a sua posição arredondada para cerca de 10 km, para escolher a localidade certa com esse nome; seu dispositivo a guarda para essa localidade</li>
          <li>RainViewer (radar de chuva) e unpkg (a biblioteca de mapas) — seu navegador os carrega diretamente ao abrir um mapa, então eles veem seu endereço IP e, no radar, a área do mapa</li>
          <li>Apple (APNs) e Google (FCM) — entregam as notificações: recebem o token push do seu celular e o texto do alerta — ambos nos EUA; Apple e Google são certificados pelo EU-US Data Privacy Framework, por isso a transferência se baseia na decisão de adequação da Comissão Europeia (art. 45 do RGPD)</li>
          <li>ImprovMX e Google (Gmail) — encaminham e guardam os e-mails enviados para info@metablend.app — a ImprovMX recebe na UE (França) e encaminha em parte por servidores nos EUA; o Google é certificado pelo EU-US Data Privacy Framework (art. 45 do RGPD)</li>
        </ul>
        <p className="mt-2">O banco de dados roda no <strong>Supabase</strong> (região UE, Frankfurt). Cada provedor trata os dados que recebe conforme a própria política de privacidade.</p>
      </> },
      { title: 'Notificações (app)', body: <>Se você ativar as notificações no app, guardamos o token push do seu celular (da Apple ou do Google), um hash de uma chave aleatória criada pelo app, sua cidade de casa, quais alertas você ativou e o horário do resumo da manhã, picos e datas planejados, seu idioma e unidade, e um registro do que enviamos nos últimos 14 dias. Não há conta nem localização. Celulares que há 90 dias não abrem o app nem recebem alertas são apagados automaticamente, e as trilhas planejadas após o seu dia. As rotas ficam no seu celular; uma rota em que você planeja uma trilha é guardada junto com o plano para enviar os alertas e apagada com ele. Desativar as notificações no app ou apagar o app as interrompe. A base jurídica é a prestação do serviço que você ativou (art. 6(1)(b) do RGPD).</> },
      { title: 'Inscrição de testadores do Android', body: <>Se você se inscrever na página de testadores para testar o app para Android, guardamos o endereço de e-mail informado e — só se você preencher — o modelo do celular e o país, além do idioma, da data e da etapa (novo, adicionado, participando, removido). O endereço é usado apenas para adicionar você ao teste fechado do MetaBlend no Google Play e enviar o link do teste; o Google passa a conhecer você como testador segundo a própria política de privacidade. Modelo do celular e país só nos ajudam a distribuir os testadores entre aparelhos e regiões. Seu endereço IP é usado brevemente na memória para evitar abusos e não o armazenamos. A lista é apagada quando o teste fechado terminar (no máximo quando o app estiver público no Google Play), ou antes se você pedir: escreva para <A href="mailto:info@metablend.app">info@metablend.app</A>. A base jurídica é seu consentimento (art. 6(1)(a) do RGPD); você pode retirá-lo a qualquer momento, com efeito futuro, pedindo a exclusão do seu cadastro.</> },
      { title: 'Por quanto tempo guardamos', body: <>Previsões armazenadas e registros internos são apagados automaticamente por uma limpeza diária (em geral em cerca de 48 horas); instantâneos do consenso e logs de erro do servidor são apagados após 30 dias. Os retornos da comunidade são mantidos enquanto alimentam o mapa público de precisão e o ranking de longo prazo das fontes — ou até você pedir a remoção (veja abaixo). Pesos de precisão agregados são anônimos e guardados por tempo indeterminado.</> },
      { title: 'Seus direitos e escolhas', body: <><p className="mb-2">Você tem direito de acesso, retificação, apagamento, limitação do tratamento, portabilidade dos dados e oposição. Para isso, escreva para <A href="mailto:info@metablend.app">info@metablend.app</A>. Você também pode apresentar uma reclamação à autoridade austríaca de proteção de dados (Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>).</p><p>Você pode usar o app sem compartilhar sua localização, apagar suas preferências locais a qualquer momento e pedir a remoção de dados de retorno abrindo uma issue no nosso <A href={ISSUES}>repositório no GitHub</A>.</p></> },
      { title: 'Contato', body: <><p className="mb-2">Dúvidas sobre privacidade? Escreva para <A href="mailto:info@metablend.app">info@metablend.app</A> ou abra uma issue em <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>. Conforme o MetaBlend evolui, este aviso pode mudar; a data de “última atualização” acima sempre indica a versão atual.</p><p>Se você entrar em contato conosco por e-mail, processamos seu endereço de e-mail e o conteúdo da sua mensagem para responder à sua solicitação (art. 6.º, n.º 1, al. b ou f do RGPD). Os dados são excluídos assim que a solicitação for concluída e não houver obrigações legais de retenção.</p></> },
    ],
  },
  ja: {
    updated: '最終更新：2026年11月',
    t1: 'プライバシー', t2: 'ポリシー',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.ja}</em><br /><br />MetaBlendは開発中の無料天気アプリで、<strong>アカウントは不要</strong>（登録は任意の Android テスター名簿だけ）です。サービスの運営と、各気象ソースの精度の測定に必要な最小限のデータだけを集めています。これはわかりやすい言葉でまとめた概要であり、法的な助言ではありません。</>,
    sections: [
      { title: '管理者', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, オーストリア<br />メール: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: '端末に保存されるもの', body: <>アプリが選択内容を覚えておけるよう、いくつかの小さな設定を端末に保存します：言語、温度の単位、外観、選択した予報期間、このポリシーへの同意、最近検索・保存した都市。最後に表示した予報はオフラインでも使えるよう保存されます。言語、単位、テーマ、同意、最近の都市はCookieに保存されるため、ページを読み込むたびに当社のサーバーに送られますが、サーバーには保存されません。それ以外はブラウザの外に出ることはありません。サイトデータを消去すればいつでもすべて削除できます。</> },
      { title: '送信された天気のフィードバック', body: <>「今の天気」を報告すると、都市、入力された気温と天気、日付、検索した都市のおおよその座標（ジオコーダーによるもので、端末のGPS位置ではありません）を保存します。これは各ソースがどれだけ近かったかの採点に使い、報告は公開の精度ヒートマップに都市単位の点として表示されます。名前、メールアドレス、アカウントとは結び付けられません。そもそもそれらは存在しないからです。 法的根拠は、気象データ源の精度を測定し改善するという当方の正当な利益です（GDPR第6条第1項(f)）。</> },
      { title: '技術的なデータ', body: <>不正利用を防ぐため、フィードバックの回数制限（1都市につき1時間に1件）にIPアドレスを一時的に使用します。このチェックのためにメモリ上でのみ使われ、フィードバックと一緒に保存されることはありません。 リクエストが失敗した場合、サーバーは要求されたアドレスをお使いの端末の位置情報なしで30日間エラーログに保存します。「現在地」の情報は含まれず、座標は約10 km単位に丸められます（GDPR第6条第1項(f)、エラー対応と安定した運用）。</> },
      { title: 'ホスティングとサーバーログ', body: <>このウェブサイトはVercel Inc.（440 N Barranca Ave #4133, Covina, CA 91723, USA）でホスティングされています。アクセス時に、Vercelは技術的に必要なデータ（IPアドレス、日時、閲覧ページ、ブラウザおよびOSの情報、直前に閲覧したページ）を処理します。これは安全で安定した運用のためです（GDPR第6条第1項f号、正当な利益）。ログファイルは限られた期間のみ保存され、その後削除されます。Vercelとはデータ処理契約を締結しています。VercelはEU-US Data Privacy Frameworkの認証を受けており、米国への移転は欧州委員会の十分性認定（GDPR第45条）に基づいて行われます。</> },
      { title: 'アクセス解析', body: <><A href={PLAUSIBLE}>Plausible Analytics</A>を使用しています。EU内でホストされるプライバシーに配慮したツールで、<strong>Cookieを使わず</strong>、個人データを収集せずに訪問数を数えます。私たちに見えるのは集計値（ページビューなど）だけで、個人ではありません。また<strong>Vercel Speed Insights</strong>でページの読み込み速度（読み込み時間などの匿名の性能値）を測定していますが、こちらもCookieを使わず、個人を特定しません。<strong>Vercel Web Analytics</strong>も同様に、Cookieを使わずにページビューを集計しています。 Plausible、Vercel Speed Insights、Vercel Web Analyticsの法的根拠は、高速なサイトを提供し、その利用状況を把握するという当方の正当な利益です（GDPR第6条第1項(f)）。PlausibleはIPアドレスを日替わりの識別子を作るために一時的に処理するのみで、保存しません。</> },
      { title: '外部サービス', body: <>
        <p className="mb-2">予報を作るために、検索された都市や座標を気象・ジオコーディングのプロバイダーに送り、データを受け取ります：</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo（ジオコーディング、大気質、過去データのアーカイブを含む） — 検索候補はブラウザから直接送られるため、Open-MeteoにIPアドレスが伝わります</li>
          <li>Photon（komoot）、OpenStreetMap、Overpass（overpass-api.de、private.coffee） — 山の検索と山頂の標高：検索テキストと、「現在地周辺」の場合は約10 kmに丸めた位置。標識のあるルートについては、サーバーが山頂の座標だけを送ります</li>
          <li>MET Norway、OpenWeatherMap、WeatherAPI、Visual Crossing、GeoSphere Austria、NWS（米国）、Bright Sky（DWD）、SMHI — およびOpen-Meteo経由のECMWF/GFS/ICON</li>
          <li>BigDataCloud — 「現在地」を使う場合のみ、座標を都市名に変換するため（逆ジオコーディング）</li>
          <li>NOAA Aviation Weather（METAR通報）とMeteostat（RapidAPI経由） — 各ソースの精度を採点する基準測定値を取得するため、サーバー側で都市の座標を受け取ります</li>
          <li>OpenStreetMap contributorsによる地図タイル（ヒートマップと雨雲レーダー）とOpenTopoMap（アプリ内のルート地図）</li>
          <li>当社のサーバー — 「現在地」を使う場合、同名の場所から正しい場所を選ぶため、約10kmに丸めた位置情報も受け取ります。端末はその場所についてこれを記憶します</li>
          <li>RainViewer（雨雲レーダー）とunpkg（地図ライブラリ） — 地図を開くとブラウザが直接読み込むため、IPアドレスと、レーダーでは地図の範囲がこれらに伝わります</li>
          <li>Apple（APNs）とGoogle（FCM） — 通知を配信します。端末のプッシュトークンと通知の本文を受け取ります — いずれも米国。AppleとGoogleはEU-US Data Privacy Frameworkの認証を受けており、移転は欧州委員会の十分性認定に基づきます（GDPR第45条）</li>
          <li>ImprovMXとGoogle（Gmail） — info@metablend.app宛のメールを転送・保存します — ImprovMXはEU（フランス）で受信し、一部は米国のサーバー経由で転送します。GoogleはEU-US Data Privacy Frameworkの認証を受けています（GDPR第45条）</li>
        </ul>
        <p className="mt-2">データベースは<strong>Supabase</strong>（EUリージョン、フランクフルト）で稼働しています。各プロバイダーは受け取ったデータをそれぞれのプライバシーポリシーに従って扱います。</p>
      </> },
      { title: '通知（アプリ）', body: <>アプリで通知をオンにすると、スマートフォンのプッシュトークン（AppleまたはGoogle発行）、アプリが作成するランダムなキーのハッシュ、ホームの都市、オンにしたアラートと朝のお知らせの時刻、計画した山と日付、言語と単位、過去14日間に送信した内容の記録を保存します。アカウントも位置情報もありません。90日間アプリを開かず通知も受け取っていない端末は自動的に削除され、計画した登山はその日を過ぎると削除されます。ルートはスマートフォンに保存されます。登山を計画したルートは、通知を送るために計画と一緒に保存され、計画とともに削除されます。アプリで通知をオフにするか、アプリを削除すると通知は止まります。 法的根拠は、お客様が有効にしたサービスの提供です（GDPR第6条第1項(b)）。</> },
      { title: 'Android テスターの登録', body: <>テスターページで Android アプリのテストに登録すると、入力されたメールアドレスと、入力された場合のみ機種と国、さらに言語・日付・進行状況（新規・追加済み・参加済み・削除）を保存します。アドレスは、Google Play の MetaBlend クローズドテストへの追加とテスト用リンクの送信にのみ使います。その後 Google は、Google 自身のプライバシーポリシーに基づいてあなたをテスターとして扱います。機種と国は、テスターを端末や地域に分散させるためだけに使います。IP アドレスは不正利用を防ぐため一時的にメモリ上で使うだけで、保存しません。名簿はクローズドテストの終了時（遅くともアプリが Google Play で一般公開された時点）に、またはご依頼があればそれより前に削除します。ご連絡は <A href="mailto:info@metablend.app">info@metablend.app</A> まで。 法的根拠はお客様の同意です（GDPR第6条第1項(a)）。削除を依頼することで、いつでも将来に向けて撤回できます。</> },
      { title: '保存期間', body: <>保存された予報と内部の管理用データは、毎日の自動クリーンアップで削除されます（通常は約48時間以内）。コンセンサスのスナップショットとサーバーのエラーログは30日後に削除されます。コミュニティのフィードバックは、公開の精度ヒートマップと長期的なソースランキングに使われている間、またはあなたから削除の依頼があるまで保存します（下記参照）。集計された精度の重みは匿名で、無期限に保存されます。</> },
      { title: '権利と選択肢', body: <><p className="mb-2">お客様には、アクセス、訂正、消去、処理の制限、データポータビリティおよび異議申立ての権利があります。ご希望の場合は<A href="mailto:info@metablend.app">info@metablend.app</A>までご連絡ください。また、オーストリアのデータ保護当局（Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>）に苦情を申し立てることもできます。</p><p>位置情報を共有せずにアプリを使うことも、端末に保存された設定をいつでも消去することもできます。フィードバックデータの削除は、<A href={ISSUES}>GitHubリポジトリ</A>でissueを作成して依頼できます。</p></> },
      { title: 'お問い合わせ', body: <><p className="mb-2">プライバシーについてのご質問は<A href="mailto:info@metablend.app">info@metablend.app</A>までメールいただくか、<A href={ISSUES}>github.com/NeverFirstTry/metablend</A>でissueを作成してください。MetaBlendの発展に伴いこのポリシーは変更されることがあります。上記の「最終更新」日が常に最新版を示します。</p><p>メールでお問い合わせいただいた場合、お問い合わせに回答するため、メールアドレスとメッセージの内容を処理します（GDPR第6条第1項b号またはf号）。データは、お問い合わせの処理が完了し、法定の保存義務がなくなり次第削除されます。</p></> },
    ],
  },
  zh: {
    updated: '最后更新：2026 年 11 月',
    t1: '隐私', t2: '声明',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.zh}</em><br /><br />MetaBlend 是一款免费、仍在开发中的天气应用，<strong>无需账号</strong>（唯一的报名是可选的 Android 测试者名单）。我们只收集运行服务和衡量各天气来源准确度所需的最少数据。这是一份通俗的概述，并非法律建议。</>,
    sections: [
      { title: '数据控制者', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, 奥地利<br />电子邮件: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: '保存在您设备上的内容', body: <>我们在本地保存少量偏好设置，让应用记住您的选择：语言、温度单位、外观、所选预报范围、您对本声明的同意，以及最近搜索和保存的城市。您最后查看的预报会被缓存，以便离线使用。语言、单位、主题、您的同意和最近的城市保存在 Cookie 中，因此每次加载页面时都会发送到我们的服务器，但服务器不会保存。其他内容都不会离开您的浏览器。您随时可以通过清除网站数据来全部删除。</> },
      { title: '您提交的天气反馈', body: <>当您报告“现在天气怎么样”时，我们会保存城市、您输入的温度和天气状况、日期，以及所搜索城市的大致地图坐标（来自我们的地理编码服务，绝不是您设备的 GPS 位置）。这些数据用于评估各来源的准确程度，报告会以城市级的点显示在公开的准确度热力图上。它们不会与您的姓名、邮箱或账号关联，因为这些都不存在。 法律依据是我们在衡量并改进各气象数据源准确性方面的正当利益（GDPR第6条第1款(f)项）。</> },
      { title: '技术数据', body: <>为防止滥用，我们会短暂使用您的 IP 地址来限制反馈频率（每个城市每小时一条）。它只在内存中用于这项检查，不会与您的反馈一起保存。 若请求失败，我们的服务器会将所请求的地址保存在错误日志中30天，不含您设备的位置信息：不包含“我的位置”的任何数据，坐标也会取整到约10公里（GDPR第6条第1款(f)项，排除故障与稳定运行）。</> },
      { title: '托管和服务器日志', body: <>本网站托管于 Vercel Inc.（440 N Barranca Ave #4133, Covina, CA 91723, USA）。访问时，Vercel 会处理技术上必需的数据：IP 地址、日期和时间、访问的页面、浏览器和操作系统信息以及之前访问的页面。这用于保障安全稳定的运行（GDPR 第 6 条第 1 款 f 项，合法利益）。日志文件仅保存有限时间，之后删除。我们已与 Vercel 签订数据处理协议。Vercel 已通过 EU-US Data Privacy Framework 认证；向美国的传输依据欧盟委员会的充分性决定（GDPR 第 45 条）进行。</> },
      { title: '统计分析', body: <>我们使用 <A href={PLAUSIBLE}>Plausible Analytics</A>，这是一款注重隐私、托管于欧盟的工具，<strong>不使用 Cookie</strong>、不收集个人数据即可统计访问量。我们只能看到汇总数字（例如页面浏览量），看不到个人。我们还使用 <strong>Vercel Speed Insights</strong> 衡量页面加载速度（加载时间等匿名性能数据），同样不使用 Cookie，也不会识别您的身份。<strong>Vercel Web Analytics</strong> 同样不使用 Cookie 统计页面浏览量。 使用Plausible、Vercel Speed Insights和Vercel Web Analytics的法律依据是我们在提供快速网站并了解其使用情况方面的正当利益（GDPR第6条第1款(f)项）。Plausible仅为生成每日更换的标识符而临时处理您的IP地址，不会存储。</> },
      { title: '第三方服务', body: <>
        <p className="mb-2">为生成预报，我们会把您搜索的城市或坐标发送给天气和地理编码服务商，并接收它们返回的数据：</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo（含地理编码、空气质量、历史档案） — 搜索建议由您的浏览器直接发送到那里，因此 Open-Meteo 能看到您的 IP 地址</li>
          <li>Photon（komoot）、OpenStreetMap 和 Overpass（overpass-api.de、private.coffee） — 山峰搜索和山顶高度：搜索文本，以及使用“我附近”时精确到约 10 公里的位置；对于有标记的路线，我们的服务器只发送山顶坐标</li>
          <li>MET Norway、OpenWeatherMap、WeatherAPI、Visual Crossing、GeoSphere Austria、NWS（美国）、Bright Sky（DWD）、SMHI — 以及通过 Open-Meteo 获取的 ECMWF/GFS/ICON</li>
          <li>BigDataCloud — 仅在您使用“我的位置”时，用于把坐标转换为城市名（逆地理编码）</li>
          <li>NOAA Aviation Weather（METAR 报告）和 Meteostat（通过 RapidAPI） — 在服务器端接收城市坐标，用于获取评估各来源准确度的参考测量值</li>
          <li>OpenStreetMap 贡献者提供的地图瓦片（热力图和降雨雷达）以及 OpenTopoMap（应用中的路线地图）</li>
          <li>我们自己的服务器 — 使用“我的位置”时，还会收到您四舍五入到约 10 公里的位置，用于选择同名地点中正确的一个；您的设备会为该地点记住它</li>
          <li>RainViewer（雨情雷达）和 unpkg（地图库） — 打开地图时您的浏览器会直接加载它们，因此它们能看到您的 IP 地址，雷达还能看到地图区域</li>
          <li>Apple（APNs）和 Google（FCM） — 传送通知：它们会收到您手机的推送令牌和通知文本 — 两者均位于美国；Apple和Google已获得欧盟-美国数据隐私框架认证，因此数据传输以欧盟委员会的充分性认定为依据（GDPR第45条）</li>
          <li>ImprovMX 和 Google（Gmail） — 转发并保存发送至 info@metablend.app 的邮件 — ImprovMX在欧盟（法国）接收邮件，并部分经由美国的服务器转发；Google已获得欧盟-美国数据隐私框架认证（GDPR第45条）</li>
        </ul>
        <p className="mt-2">数据库运行在 <strong>Supabase</strong>（欧盟区域，法兰克福）。各服务商按照各自的隐私政策处理所收到的数据。</p>
      </> },
      { title: '通知（应用）', body: <>如果您在应用中开启通知，我们会保存您手机的推送令牌（来自 Apple 或 Google）、应用生成的随机密钥的哈希值、您的常住城市、您开启的提醒和早间简报时间、计划的山峰和日期、您的语言和单位，以及过去 14 天发送记录。没有账号，也没有位置信息。90 天未打开应用且未收到任何通知的手机会被自动删除，计划的徒步在其日期过后删除。路线保存在您的手机上；您计划徒步的路线会随计划一起保存以便发送提醒，并随计划一起删除。在应用中关闭通知或删除应用即可停止通知。 法律依据是提供您所开启的服务（GDPR第6条第1款(b)项）。</> },
      { title: 'Android 测试者报名', body: <>如果您在测试者页面报名测试 Android 应用，我们会保存您填写的邮箱地址，以及（仅在您填写时）手机型号和国家/地区，另外还有您的语言、日期和所处阶段（新报名、已添加、已加入、已移除）。邮箱仅用于把您加入 MetaBlend 在 Google Play 上的封闭测试并发送测试链接；之后 Google 会依据其自己的隐私政策将您视为测试者。手机型号和国家/地区仅用于让测试者分布在不同设备和地区。您的 IP 地址仅在内存中短暂用于防止滥用，我们不会保存。名单会在封闭测试结束时（最迟在应用于 Google Play 公开发布时）删除，或应您的要求提前删除：请发邮件至 <A href="mailto:info@metablend.app">info@metablend.app</A>。 法律依据是您的同意（GDPR第6条第1款(a)项）；您可以随时请求删除，从而撤回同意，自撤回起生效。</> },
      { title: '保存多久', body: <>保存的预报和内部记录由每日清理任务自动删除（通常约 48 小时内）；共识快照和服务器错误日志在 30 天后删除。社区反馈会一直保留，只要它们仍用于公开的准确度热力图和长期来源排名 — 或直到您要求删除（见下文）。汇总的准确度权重是匿名的，会无限期保留。</> },
      { title: '您的权利和选择', body: <><p className="mb-2">您有权访问、更正、删除、限制处理、数据可携以及提出异议。如需行使这些权利，请写信至 <A href="mailto:info@metablend.app">info@metablend.app</A>。您也可以向奥地利数据保护机构投诉（Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>）。</p><p>您可以在不分享位置的情况下使用本应用，随时清除本地保存的偏好，也可以在我们的 <A href={ISSUES}>GitHub 仓库</A>提交 issue，要求删除反馈数据。</p></> },
      { title: '联系我们', body: <><p className="mb-2">有隐私方面的问题？请发邮件至 <A href="mailto:info@metablend.app">info@metablend.app</A>，或在 <A href={ISSUES}>github.com/NeverFirstTry/metablend</A> 提交 issue。随着 MetaBlend 的发展，本声明可能会更新；上方的“最后更新”日期始终对应当前版本。</p><p>如果您通过电子邮件与我们联系，我们会处理您的电子邮件地址和消息内容，以回复您的询问（GDPR 第 6 条第 1 款 b 项或 f 项）。询问处理完毕且不存在法定保存义务后，数据将被删除。</p></> },
    ],
  },
  ko: {
    updated: '최종 업데이트: 2026년 11월',
    t1: '개인정보 ', t2: '처리방침',
    intro: <><em className="text-zinc-500">{TRANSLATION_NOTE.ko}</em><br /><br />MetaBlend는 개발 중인 무료 날씨 앱으로, <strong>계정이 필요 없습니다</strong>(가입은 선택 사항인 Android 테스터 명단뿐입니다). 서비스를 운영하고 각 기상 출처의 정확도를 측정하는 데 필요한 최소한의 데이터만 수집합니다. 이 문서는 쉬운 말로 정리한 요약이며 법률 자문이 아닙니다.</>,
    sections: [
      { title: '개인정보 처리 책임자', body: <>Rene Kostmann, Siedlerstraße 19, 9900 Lienz, 오스트리아<br />이메일: <A href="mailto:info@metablend.app">info@metablend.app</A></> },
      { title: '기기에 남는 정보', body: <>앱이 선택을 기억할 수 있도록 몇 가지 작은 설정을 기기에 저장합니다: 언어, 온도 단위, 화면 모드, 선택한 예보 기간, 이 방침에 대한 동의, 최근 검색하고 저장한 도시. 마지막으로 본 예보는 오프라인에서도 쓸 수 있도록 저장됩니다. 언어, 단위, 테마, 동의 여부, 최근 도시는 쿠키에 저장되므로 페이지를 불러올 때마다 서버로 전송되지만 서버에는 저장되지 않습니다. 그 밖의 정보는 브라우저 밖으로 나가지 않습니다. 사이트 데이터를 지우면 언제든 모두 삭제할 수 있습니다.</> },
      { title: '보내 주신 날씨 피드백', body: <>“지금 날씨”를 보고하면 도시, 입력한 기온과 날씨 상태, 날짜, 검색한 도시의 대략적인 지도 좌표(지오코더에서 가져온 것으로, 기기의 GPS 위치는 절대 아님)를 저장합니다. 이는 각 출처가 얼마나 정확했는지 채점하는 데 쓰이며, 보고는 공개 정확도 히트맵에 도시 단위의 점으로 표시됩니다. 이름, 이메일, 계정과는 연결되지 않습니다. 애초에 그런 것이 없기 때문입니다. 법적 근거는 기상 데이터 출처의 정확도를 측정하고 개선하려는 당사의 정당한 이익입니다(GDPR 제6조 제1항 (f)호).</> },
      { title: '기술 데이터', body: <>남용을 막기 위해 피드백 횟수 제한(도시당 1시간에 1건)에 IP 주소를 잠시 사용합니다. 이 확인을 위해 메모리에서만 쓰이고, 피드백과 함께 저장되지 않습니다. 요청이 실패하면 서버는 요청된 주소를 귀하의 기기 위치 정보 없이 30일 동안 오류 로그에 보관합니다. ‘내 위치’의 정보는 포함되지 않으며 좌표는 약 10 km 단위로 반올림됩니다(GDPR 제6조 제1항 (f)호, 오류 해결과 안정적인 운영).</> },
      { title: '호스팅 및 서버 로그', body: <>이 웹사이트는 Vercel Inc.(440 N Barranca Ave #4133, Covina, CA 91723, USA)에서 호스팅됩니다. 접속 시 Vercel은 기술적으로 필요한 데이터, 즉 IP 주소, 날짜 및 시간, 요청한 페이지, 브라우저 및 운영체제 정보, 이전에 방문한 페이지를 처리합니다. 이는 안전하고 안정적인 운영을 위한 것입니다(GDPR 제6조 제1항 f호, 정당한 이익). 로그 파일은 제한된 기간 동안만 저장된 후 삭제됩니다. Vercel과 데이터 처리 계약을 체결했습니다. Vercel은 EU-US Data Privacy Framework 인증을 받았으며, 미국으로의 이전은 유럽연합 집행위원회의 적정성 결정(GDPR 제45조)에 근거합니다.</> },
      { title: '분석', body: <><A href={PLAUSIBLE}>Plausible Analytics</A>를 사용합니다. EU에서 호스팅되는 개인정보 친화적인 도구로, <strong>쿠키 없이</strong> 개인정보를 수집하지 않고 방문 수를 셉니다. 저희는 합계(예: 페이지 조회수)만 볼 수 있고 개인은 볼 수 없습니다. 또한 <strong>Vercel Speed Insights</strong>로 페이지 로딩 속도(로딩 시간 같은 익명의 성능 수치)를 측정하는데, 이 역시 쿠키를 쓰지 않고 사용자를 식별하지 않습니다. <strong>Vercel Web Analytics</strong>도 쿠키 없이 페이지 조회수를 집계합니다. Plausible, Vercel Speed Insights, Vercel Web Analytics의 법적 근거는 빠른 웹사이트를 제공하고 그 이용 현황을 파악하려는 당사의 정당한 이익입니다(GDPR 제6조 제1항 (f)호). Plausible은 매일 바뀌는 식별자를 만들기 위해 IP 주소를 일시적으로만 처리하며 저장하지 않습니다.</> },
      { title: '외부 서비스', body: <>
        <p className="mb-2">예보를 만들기 위해 검색한 도시나 좌표를 날씨·지오코딩 제공업체에 보내고 데이터를 받습니다:</p>
        <ul className="list-disc pl-5 space-y-0.5 text-zinc-400">
          <li>Open-Meteo(지오코딩, 대기질, 과거 기록 포함) — 검색 제안은 브라우저에서 직접 전송되므로 Open-Meteo가 IP 주소를 볼 수 있습니다</li>
          <li>Photon(komoot), OpenStreetMap, Overpass(overpass-api.de, private.coffee) — 산 검색과 정상 고도: 검색어와, “내 주변” 사용 시 약 10 km로 반올림한 위치. 표시된 경로의 경우 서버는 정상 좌표만 보냅니다</li>
          <li>MET Norway, OpenWeatherMap, WeatherAPI, Visual Crossing, GeoSphere Austria, NWS(미국), Bright Sky(DWD), SMHI — 그리고 Open-Meteo를 통한 ECMWF/GFS/ICON</li>
          <li>BigDataCloud — “내 위치”를 사용할 때만, 좌표를 도시 이름으로 바꾸기 위해(역지오코딩)</li>
          <li>NOAA Aviation Weather(METAR 보고)와 Meteostat(RapidAPI 경유) — 각 출처의 정확도를 채점할 기준 측정값을 가져오기 위해 서버에서 도시 좌표를 받습니다</li>
          <li>OpenStreetMap 기여자의 지도 타일(히트맵과 강수 레이더)과 OpenTopoMap(앱의 경로 지도)</li>
          <li>자체 서버 — “내 위치”를 사용하면 같은 이름의 장소 중 올바른 곳을 고르기 위해 약 10km로 반올림한 위치도 받습니다. 기기는 그 장소에 대해 이 위치를 기억합니다</li>
          <li>RainViewer(강수 레이더)와 unpkg(지도 라이브러리) — 지도를 열면 브라우저가 직접 불러오므로 IP 주소와, 레이더의 경우 지도 영역을 볼 수 있습니다</li>
          <li>Apple(APNs)과 Google(FCM) — 알림을 전달하며, 휴대폰의 푸시 토큰과 알림 내용을 받습니다 — 두 곳 모두 미국 소재이며, Apple과 Google은 EU-US 데이터 프라이버시 프레임워크 인증을 받았으므로 이전은 유럽연합 집행위원회의 적정성 결정에 근거합니다(GDPR 제45조)</li>
          <li>ImprovMX와 Google(Gmail) — info@metablend.app으로 보낸 이메일을 전달하고 보관합니다 — ImprovMX는 EU(프랑스)에서 수신하고 일부는 미국 서버를 거쳐 전달합니다. Google은 EU-US 데이터 프라이버시 프레임워크 인증을 받았습니다(GDPR 제45조)</li>
        </ul>
        <p className="mt-2">데이터베이스는 <strong>Supabase</strong>(EU 리전, 프랑크푸르트)에서 운영됩니다. 각 제공업체는 받은 데이터를 자체 개인정보 처리방침에 따라 처리합니다.</p>
      </> },
      { title: '알림(앱)', body: <>앱에서 알림을 켜면 휴대폰의 푸시 토큰(Apple 또는 Google 발급), 앱이 만든 무작위 키의 해시, 내 도시, 켠 알림과 아침 브리핑 시각, 계획한 산과 날짜, 언어와 단위, 최근 14일간 보낸 내용의 기록을 저장합니다. 계정도 위치 정보도 없습니다. 90일 동안 앱을 열지 않고 알림도 받지 않은 휴대폰은 자동으로 삭제되며, 계획한 등산은 그날이 지나면 삭제됩니다. 경로는 휴대폰에 남습니다. 등산을 계획한 경로는 알림을 보내기 위해 계획과 함께 저장되고, 계획과 함께 삭제됩니다. 앱에서 알림을 끄거나 앱을 삭제하면 알림이 멈춥니다. 법적 근거는 귀하가 켠 서비스의 제공입니다(GDPR 제6조 제1항 (b)호).</> },
      { title: 'Android 테스터 신청', body: <>테스터 페이지에서 Android 앱 테스트를 신청하면 입력한 이메일 주소와, 입력한 경우에만 휴대폰 모델과 국가, 그리고 언어, 날짜, 진행 상태(신규, 추가됨, 참여함, 제외됨)를 저장합니다. 주소는 Google Play의 MetaBlend 비공개 테스트에 추가하고 테스트 링크를 보내는 데에만 사용합니다. 이후 Google은 자체 개인정보처리방침에 따라 귀하를 테스터로 인식합니다. 휴대폰 모델과 국가는 테스터를 여러 기기와 지역에 고르게 나누는 데에만 사용합니다. IP 주소는 남용을 막기 위해 메모리에서 잠시 사용할 뿐 저장하지 않습니다. 명단은 비공개 테스트가 끝나면(늦어도 앱이 Google Play에 공개되면), 또는 요청하면 그 전에 삭제합니다. 연락은 <A href="mailto:info@metablend.app">info@metablend.app</A>으로 해 주십시오. 법적 근거는 귀하의 동의입니다(GDPR 제6조 제1항 (a)호). 삭제를 요청하시면 언제든지 장래를 향해 동의를 철회할 수 있습니다.</> },
      { title: '보관 기간', body: <>저장된 예보와 내부 관리용 기록은 매일 실행되는 정리 작업으로 자동 삭제됩니다(보통 약 48시간 이내). 합의 스냅숏과 서버 오류 로그는 30일 후 삭제됩니다. 커뮤니티 피드백은 공개 정확도 히트맵과 장기 출처 순위에 쓰이는 동안, 또는 삭제를 요청하실 때까지 보관합니다(아래 참고). 집계된 정확도 가중치는 익명이며 무기한 보관됩니다.</> },
      { title: '귀하의 권리와 선택', body: <><p className="mb-2">귀하는 열람, 정정, 삭제, 처리 제한, 데이터 이동 및 이의 제기의 권리를 가집니다. 이를 위해 <A href="mailto:info@metablend.app">info@metablend.app</A>으로 연락하십시오. 또한 오스트리아 데이터 보호 당국(Barichgasse 40–42, 1030 Wien, <A href="https://www.dsb.gv.at">www.dsb.gv.at</A>)에 불만을 제기할 수 있습니다.</p><p>위치를 공유하지 않고도 앱을 쓸 수 있고, 기기에 저장된 설정을 언제든 지울 수 있으며, <A href={ISSUES}>GitHub 저장소</A>에 issue를 열어 피드백 데이터 삭제를 요청할 수 있습니다.</p></> },
      { title: '문의', body: <><p className="mb-2">개인정보 관련 문의는 <A href="mailto:info@metablend.app">info@metablend.app</A>로 메일을 보내거나 <A href={ISSUES}>github.com/NeverFirstTry/metablend</A>에 issue를 열어 주십시오. MetaBlend가 발전함에 따라 이 방침은 바뀔 수 있으며, 위의 “최종 업데이트” 날짜가 항상 최신 버전을 나타냅니다.</p><p>이메일로 문의하시면 문의에 답변하기 위해 이메일 주소와 메시지 내용을 처리합니다(GDPR 제6조 제1항 b호 또는 f호). 문의가 처리되고 법정 보존 의무가 없으면 데이터는 삭제됩니다.</p></> },
    ],
  },
}

export default function PrivacyContent() {
  return <PrivacyBody lang={useLang()} />
}

export function PrivacyBody({ lang }) {
  const c = CONTENT[lang] ?? CONTENT.en

  return (
    <main className="min-h-screen bg-[#0e0e12] text-white font-mono p-4 sm:p-8 overflow-x-hidden">
      <div className="max-w-2xl mx-auto">
        <Link href="/" className="app-only text-zinc-500 text-sm hover:text-emerald-400 transition-colors mb-6 inline-flex items-center gap-1.5">
          <ArrowLeft size={15} aria-hidden /> {t(lang, 'back')}
        </Link>

        <h1 className="text-3xl font-bold mb-1">{c.t1}<span className="text-emerald-400">{c.t2}</span></h1>
        <p className="text-zinc-500 text-sm mb-8 tracking-widest uppercase">{c.updated}</p>

        <div className="space-y-6 text-sm leading-relaxed text-zinc-300">
          <p className="text-zinc-400">{c.intro}</p>
          {c.sections.map(s => (
            <Section key={s.title} title={s.title}>{s.body}</Section>
          ))}
        </div>

        <Footer lang={lang} />
      </div>
    </main>
  )
}

function Section({ title, children }) {
  return (
    <section>
      <h2 className="text-emerald-400 text-xs uppercase tracking-widest mb-2">{title}</h2>
      <div className="text-zinc-300">{children}</div>
    </section>
  )
}
